/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A40 staging · exact frozen manifest greenish–guild (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('greenish','greenish 由 green 加后缀 -ish 构成，表示颜色有些发绿、带浅绿色调，而不一定是纯绿色。',C('greenish.s1','颜色描述','The old copper roof had a greenish tint where rainwater had weathered the metal over many years.','旧铜屋顶被雨水侵蚀多年之处泛着浅绿色。','The old copper roof had a greenish tint / where rainwater had weathered the metal / over many years.','greenish 修饰 tint，表示略带绿色；where 从句描述出现颜色的区域。','颜色只是略微发绿，符合 -ish 的“有点、略带”义。'),M('The greenish paint was perfectly pure white with no trace of green.','The whitish paint was nearly white with no trace of green.','纯白且没有绿色成分不应称 greenish。'),[Q('greenish',1,1,'A greenish surface is?','somewhat green in color','completely colorless','bright red throughout','greenish 表示略带绿色。'),Q('greenish',2,1,'Which object might look greenish?','old copper developing a pale green patina','fresh snow under a clear sky','a black stone with no lighter areas','铜表面可形成浅绿色锈层。'),Q('greenish',3,1,'The suffix -ish in greenish suggests?','a degree or resemblance, not necessarily pure green','a person who studies plants','an exact scientific measurement','-ish 常表示“有点像、略带”。'),Q('greenish',4,1,'Choose the closest paraphrase of a greenish light.','a light with a slight green tint','a light that is entirely blue','a light that gives no visible color','略带绿调的灯光符合释义。')]);
P('greens','greens 是 green 的复数形式，在食物语境中常指绿叶蔬菜或青菜。',C('greens.s1','饮食与购物','She bought fresh greens from the market and washed the leaves thoroughly before adding them to the soup.','她从市场买了新鲜青菜，仔细洗净叶片后才把它们加入汤里。','She bought fresh greens from the market / and washed the leaves thoroughly / before adding them to the soup.','greens 作复数名词指绿叶蔬菜；them 指代叶菜。','洗净叶片并加入汤中，说明 greens 指可食用青菜。'),M('The recipe called for greens, so he added a bag of green plastic beads to the soup.','The recipe called for leafy greens, so he added washed spinach to the soup.','塑料珠不是可食用青菜。'),[Q('greens',1,1,'On a shopping list, greens usually means?','green vegetables, especially leafy ones','green paint for a wall','unripe fruit only','greens 在饮食中指青菜或绿叶蔬菜。'),Q('greens',2,1,'Which item belongs in a salad of greens?','spinach leaves','plastic beads','a metal grid','菠菜叶是绿叶蔬菜。'),Q('greens',3,1,'Why might someone wash greens before cooking?','to clean the vegetable leaves','to remove their green color completely','to turn them into grain','蔬菜叶需要洗净再烹饪。'),Q('greens',4,1,'In “eat your greens,” greens refers to?','vegetables','green clothes','young trees only','这句常指吃蔬菜。')]);
P('greet','greet 源自古英语 grētan，早期有“接近、拜访”之意；现代可指问候、迎接，也可指某事物首先映入眼帘或引发反应。',C('greet.s3','环境描写','When Mara opened the door, a wall of warm air greeted her, followed by the smell of bread from the kitchen.','玛拉打开门时，一股暖空气迎面而来，随后闻到了厨房飘来的面包香。','When Mara opened the door / a wall of warm air greeted her / followed by the smell of bread / from the kitchen.','warm air greeted her 是拟人表达，指首先感受到；followed by 补充随后出现的感官信息。','暖空气首先映入感官，符合 s3。'),M('The first thing that greeted him was a silent room, but he heard a loud welcome before opening the door.','The first thing that greeted him was a loud welcome, which he heard as he opened the door.','“silent room”与“听到响亮欢迎”互相矛盾，应明确先听到的内容。'),[Q('greet',1,1,'To greet a visitor is to?','say hello or welcome the person','measure the visitor’s height','hide every sign that the visitor arrived','greet 的常见义是问候或欢迎。'),Q('greet',2,2,'A crowd greeted the announcement with silence. Here greeted means the crowd?','responded to it in a particular way','said hello to the announcer personally','delivered the announcement','greet 可表示以某种反应回应。'),Q('greet',3,3,'“A bright view greeted us at the summit” means the view?','was the first thing we saw','welcomed us with spoken words','was hidden behind the mountain','greet 也可指首先映入眼帘。'),Q('greet',4,1,'Which action is a greeting?','welcoming a guest at the door','testing a kitchen grill','drawing a map grid','在门口欢迎客人是 greet。')]);
P('greeting','greeting 由 greet 加 -ing 构成名词，指见面或迎接时说的话、表达的问候。',C('greeting.s1','礼仪交流','Her greeting was brief but warm: she thanked the visitors for coming and introduced them to the rest of the team.','她的问候简短而热情：她感谢访客到来，并把他们介绍给团队其他成员。','Her greeting was brief but warm / she thanked the visitors for coming / and introduced them / to the rest of the team.','greeting 作名词指问候的话语；冒号后说明其内容。','感谢来访并作介绍属于见面时的问候表达。'),M('His greeting told the visitors to leave immediately and never return.','His order told the visitors to leave immediately and never return.','赶人离开是命令，不是问候。'),[Q('greeting',1,1,'A greeting is?','words said when meeting or welcoming someone','a complaint about unfair treatment','a tool for grinding grain','greeting 指见面时的问候语。'),Q('greeting',2,1,'Which is a friendly greeting?','“Good morning; it is nice to see you.”','“You are not allowed to enter.”','“The bridge is three miles long.”','友好地打招呼是 greeting。'),Q('greeting',3,1,'A greeting at the start of a letter might be?','Dear Dr. Lee,','Sincerely yours,','Attachment: invoice','信件开头的称呼语可作 greeting。'),Q('greeting',4,1,'The closest meaning of greeting is?','salutation','grievance','guarantee','salutation 表示问候、致意。')]);
P('greetings','greetings 是 greeting 的复数形式，可指寄给某人的祝福语、问候语，常用于节日或问候卡。',C('greetings.s1','节日通信','The postcard carried greetings from the whole family, wishing their grandparents a peaceful holiday by the sea.','明信片上有全家送给祖父母的问候，祝他们在海边度过宁静的假期。','The postcard carried greetings from the whole family / wishing their grandparents / a peaceful holiday / by the sea.','greetings from + 发送问候的人；wishing 引出祝福内容。','全家寄送祝福和问候，符合复数义。'),M('The card sent greetings by wishing the grandparents misery and asking them not to reply.','The card sent ill wishes by wishing the grandparents misery and asking them not to reply.','祝愿别人不幸不是友好的 greetings。'),[Q('greetings',1,1,'“Season’s greetings” is a way to send?','kind wishes during a holiday period','a legal complaint','a warning about a grenade','greetings 可指节日期间的祝福。'),Q('greetings',2,1,'A postcard with greetings from friends contains?','friendly messages to the recipient','a list of unpaid bills only','instructions for repairing a grill','明信片上的问候语传递友好信息。'),Q('greetings',3,1,'Which phrase is a common use of greetings?','Greetings from Paris!','Grounds for dismissal!','A grievance in the kitchen!','Greetings from Paris 是常见问候语。'),Q('greetings',4,1,'The singular form of greetings is?','greeting','greet','greeted','greetings 是 greeting 的复数。')]);
P('gregarious','gregarious 源自拉丁语 gregarius“属于群体的”，可形容喜欢与人交往的人，也可指喜欢成群生活的动物。',C('gregarious.s2','动物行为','The gregarious seabirds nested in a dense colony, with hundreds of pairs sharing the same rocky island.','这些群居海鸟在密集的群落中筑巢，数百对鸟共同生活在同一座岩岛上。','The gregarious seabirds nested in a dense colony / with hundreds of pairs / sharing the same rocky island.','gregarious 修饰 seabirds，指动物群居；with 短语说明聚居规模。','鸟类集体筑巢而非独居，体现 s2。'),M('The gregarious seabird avoided every colony and lived alone in a remote cave.','The solitary seabird avoided every colony and lived alone in a remote cave.','独居与喜欢群体生活相反。'),[Q('gregarious',1,1,'A gregarious person usually?','enjoys being with other people','avoids all social contact','prefers to live underground','gregarious 可形容爱交际的人。'),Q('gregarious',2,2,'A gregarious animal tends to?','live in groups with others of its kind','hunt only in complete isolation','avoid every other animal','动物义表示群居。'),Q('gregarious',3,1,'Which person seems gregarious?','someone who enjoys meeting new people at gatherings','someone who leaves every party immediately','someone who refuses to speak to anyone','喜欢在聚会认识新朋友体现爱交际。'),Q('gregarious',4,1,'A gregarious species is closest to a?','social species','solitary species','extinct species','social species 群居，与 gregarious 接近。')]);
P('grenade','grenade 经法语 grenade 进入英语，指可投掷的小型爆炸装置；词源与“石榴”一词有关，但现代词义是军械。',C('grenade.s1','新闻与安全','The report said police closed the square after finding an unexploded grenade, and bomb-disposal specialists secured the area.','报道说，警方发现一枚未爆手榴弹后封锁了广场，拆弹专家控制了现场。','The report said police closed the square / after finding an unexploded grenade / and bomb-disposal specialists / secured the area.','grenade 是小型爆炸装置名词；报道聚焦发现后的安全处置，不涉及操作。','发现未爆军械后封锁现场，符合 grenade 的名词义。'),M('The reporter described the grenade as a harmless greeting card that could be opened safely by children.','The reporter described the object as a greeting card after specialists confirmed it was harmless.','grenade 是爆炸装置，不能轻率称为儿童可安全打开的卡片。'),[Q('grenade',1,1,'A grenade is?','a small explosive device designed to be thrown','a type of seabird','a tool for measuring soil moisture','grenade 指可投掷的小型爆炸装置。'),Q('grenade',2,1,'What is the appropriate response to a suspected grenade?','keep away and alert trained authorities','pick it up to inspect the markings','take it home for a closer look','发现疑似爆炸物应远离并通知专业人员。'),Q('grenade',3,1,'A news report about a grenade most likely concerns?','an explosive device found by police','a polite phrase in a letter','a kitchen grill used for vegetables','grenade 是军械，不是问候语或厨具。'),Q('grenade',4,1,'Which word is closest to grenade’s category?','explosive device','garden plant','family record','grenade 属于爆炸装置。')]);
P('grey','grey 是英式常见拼写，源自古英语 grǣg；可作形容词表示介于黑白之间或阴沉，也可作动词表示变灰。',C('grey.s1','天气与色彩','The sky turned grey before the rain began, and the mountain ridge disappeared behind a layer of low cloud.','下雨前天空转为灰暗，山脊也消失在低云之后。','The sky turned grey before the rain began / and the mountain ridge disappeared / behind a layer of low cloud.','grey 作形容词描述颜色或阴沉天气；turn grey 表示变为灰色。','阴云使天空发灰、天色阴沉，符合 s1。'),M('The sky turned grey, becoming bright yellow and cloudless.','The sky turned golden, becoming bright yellow and cloudless.','明亮黄色且无云与变灰相反。'),[Q('grey',1,1,'Grey is a color between?','black and white','red and orange','blue and green','grey 指介于黑白之间的颜色。'),Q('grey',2,1,'In British spelling, grey corresponds to American?','gray','green','grill','grey 是英式常见拼法，gray 为美式常见拼法。'),Q('grey',3,2,'If a person’s hair greys, it?','becomes grey','is cut into a grid','turns into a greeting','动词 grey 表示变灰。'),Q('grey',4,1,'A grey, sunless afternoon is likely?','dull and overcast','bright and cloudless','hot and brightly colored','grey 可形容阴暗无阳光。')]);
P('grid','grid 可能源自 gridiron 的缩略形式，可指横竖线构成的网格、电力输送网络或地图定位用的坐标方格。',C('grid.s2','电力系统','The utility rerouted power through a regional grid after the storm damaged several transmission lines near the coast.','风暴损坏海岸附近数条输电线后，电力公司改由区域电网输送电力。','The utility rerouted power through a regional grid / after the storm damaged / several transmission lines / near the coast.','grid 在此指供电网络；through 引出电力输送路径。','区域网络重新输送电力，符合电网义 s2。'),M('The regional grid was a single pencil line on a map with no cables or electricity network.','The map grid was a set of lines for locating places, not an electricity network.','地图线格不等同于供电网络。'),[Q('grid',1,1,'A street grid is?','a pattern of intersecting lines or streets','a group of birds living together','a small explosive device','grid 可指横竖线构成的网格。'),Q('grid',2,2,'The electrical grid supplies?','electricity through a network of cables','food through a garden plot','directions through a greeting card','电网通过网络输送电力。'),Q('grid',3,3,'A map grid helps a user?','locate places using square coordinates','cook food over direct heat','measure a person’s grief','地图坐标方格帮助定位地点。'),Q('grid',4,1,'Which sentence uses grid to mean an electricity network?','The city restored power to the grid.','The map grid labeled each square.','A metal grid covered the drain.','restored power to the grid 指电网。')]);
P('gridiron','gridiron 由 grid 与 iron 构成，原指横杆式烤架，也可指美式橄榄球场；球场线条呈网格状，形成其体育义。',C('gridiron.s1','户外烹饪','The cook placed the fish on a gridiron above the coals, turning it once when the underside had browned.','厨师把鱼放在炭火上方的烤架上，底面变褐后翻了一次。','The cook placed the fish on a gridiron above the coals / turning it once / when the underside had browned.','gridiron 作名词指金属烤架；above the coals 说明烹饪方式。','食物置于炭火上方的架子烤制，符合 s1。'),M('The cook put the fish on a gridiron, a bowl of cold water used for washing vegetables.','The cook put the fish on a gridiron, a metal rack used for grilling food.','gridiron 是烤架，不是盛水的碗。'),[Q('gridiron',1,1,'A gridiron used in cooking is?','a metal rack for grilling food','a container for storing cold water','a map coordinate system','gridiron 可指烤架。'),Q('gridiron',2,1,'In American sports, the gridiron is?','a football field','an aircraft kitchen','a type of family tree','gridiron 也指橄榄球场。'),Q('gridiron',3,1,'Why is a football field nicknamed the gridiron?','its marked lines form a grid-like pattern','players cook meals on it','it is made entirely of iron','球场线条像网格，形成这一俗称。'),Q('gridiron',4,1,'Which object belongs over hot coals?','a gridiron','a gazette','a guardian','烤架可以放在炭火上方烹饪。')]);
P('grief','grief 经古法语 grief“痛苦、悲伤”进入英语，可指深切悲痛、引起悲痛的事，也可指哀悼的一段时期。',C('grief.s3','哀悼过程','After the funeral, the family took time to grieve in private, recognizing that grief does not follow the same timetable for everyone.','葬礼后，家人留出时间私下哀悼，并认识到每个人的悲痛过程并不同步。','After the funeral / the family took time to grieve in private / recognizing that grief does not follow / the same timetable for everyone.','grief 指哀伤或哀悼期；that 从句说明哀悼过程因人而异。','葬礼后的哀悼过程体现 grief 的 s3。'),M('Her grief after the loss was cheerful celebration and never involved sadness or mourning.','Her response after the loss was cheerful celebration, not grief or mourning.','庆祝而无悲伤并非 grief。'),[Q('grief',1,1,'Grief is deep sadness often caused by?','the death or loss of someone important','a small change in the weather','winning a friendly game','grief 常指因死亡或失去而产生的深切悲伤。'),Q('grief',2,2,'A source of grief is?','something that causes great sadness','a tool used for grilling food','a map coordinate','grief 也可指引起悲痛的事物。'),Q('grief',3,3,'A period of grief is a time of?','mourning after a loss','celebration before a wedding','training for a football match','grief 可指哀悼期。'),Q('grief',4,1,'The closest synonym for grief is?','sorrow','greeting','gaiety','sorrow 表示悲伤。')]);
P('grievance','grievance 由 grieve 加 -ance 构成，指认为受到不公平对待而提出的抱怨或申诉。',C('grievance.s1','劳动关系','The union filed a grievance after the company changed shift schedules without notice, asking management to follow the terms of the contract.','公司未经通知就更改轮班表后，工会提出申诉，要求管理层遵守合同条款。','The union filed a grievance / after the company changed shift schedules without notice / asking management / to follow the terms of the contract.','file a grievance 是正式提出不满或申诉；after 指明申诉原因。','员工认为公司违反公平程序，因此提出正式投诉。'),M('The employee filed a grievance to praise the fair schedule and request that management change nothing.','The employee filed a commendation to praise the fair schedule and request that management change nothing.','赞扬公平安排不是对不公平待遇的 grievance。'),[Q('grievance',1,1,'A workplace grievance is?','a complaint about unfair treatment','a greeting sent for a holiday','a guarantee for a new appliance','grievance 指对不公待遇的不满或申诉。'),Q('grievance',2,1,'Which issue could lead to a grievance?','an employer withholds wages promised in the contract','a manager thanks the staff for their work','a worker receives the agreed break','违反合同承诺可能引发申诉。'),Q('grievance',3,1,'To file a grievance usually means to?','formally raise a complaint','withdraw every concern','offer a congratulatory greeting','提出申诉常需正式表达。'),Q('grievance',4,1,'The closest word to grievance is?','complaint','celebration','guarantee','complaint 表示抱怨或投诉。')]);
P('grieve','grieve 源于古法语 grever“使负担沉重、使悲伤”，现代通常指因失去亲友而深切悲痛，也可泛指悲伤。',C('grieve.s1','失亲后的支持','Friends gave Amira room to grieve after her father died, offering practical help without pressuring her to feel better quickly.','父亲去世后，朋友给阿米拉留出哀伤的空间，提供实际帮助，却不催促她尽快好起来。','Friends gave Amira room to grieve / after her father died / offering practical help / without pressuring her to feel better quickly.','grieve 表示悲伤、哀悼；room to grieve 是允许对方经历悲痛的说法。','亲人去世后经历悲痛，符合动词义。'),M('She grieved at the joyful news because she felt delighted and celebrated all evening.','She rejoiced at the joyful news because she felt delighted and celebrated all evening.','欢欣庆祝不属于 grieve。'),[Q('grieve',1,1,'To grieve after a death is to?','feel deep sadness and mourn the loss','celebrate the death as a happy event','measure the distance to a grave','grieve 指因失去而悲痛。'),Q('grieve',2,1,'A friend can support someone who grieves by?','listening and offering help without rushing the person','demanding that sadness end immediately','ignoring the person’s loss','耐心倾听并提供帮助有助支持哀伤者。'),Q('grieve',3,1,'Which sentence uses grieve naturally?','The family grieved together after the loss.','The family grieved the cake at the bakery.','The family grieved the square into a circle.','grieve 通常指因失去而悲伤。'),Q('grieve',4,1,'The closest opposite of grieve in a joyful context is?','rejoice','mourn','lament','rejoice 表示欣喜。')]);
P('grieved','grieved 是 grieve 的过去分词形容词，可表示因失去而悲痛，也可表示因某件错误或不公平的事而难过。',C('grieved.s2','不公事件','She felt grieved by the unfair accusation, especially because the evidence clearing her name had been available from the beginning.','她因这项不公平指控而难过，尤其是因为一开始就有能证明她清白的证据。','She felt grieved by the unfair accusation / especially because the evidence / clearing her name / had been available from the beginning.','be grieved by + 令人难过的事；clearing her name 修饰 evidence。','不公指控及被忽略的证据使她难过，符合 s2。'),M('He was grieved by the fair decision because it pleased everyone and caused no distress.','He was pleased by the fair decision because it pleased everyone and caused no distress.','公平决定令人满意且没有造成痛苦，与 grieved 不符。'),[Q('grieved',1,1,'A grieved person is?','deeply sad after a loss','certainly pleased by everything','unable to hear sounds','grieved 可表示因失去而悲痛。'),Q('grieved',2,2,'Someone may feel grieved by?','an unfair accusation or painful wrong','a harmless routine greeting','a sunny day with no problems','grieved 也可表示因不公或错误而难过。'),Q('grieved',3,1,'Which sentence is natural?','The grieved family gathered after the funeral.','The grieved family means the family caused the funeral.','The family grieved a greeting card onto the table.','grieved family 指悲痛的家人。'),Q('grieved',4,2,'If an employee is grieved by a decision, the employee is?','upset because something wrong has happened','delighted by the decision','measuring it with a grid','该词可指因错误或不公而难过。')]);
P('grievous','grievous 经古法语源自拉丁语 gravis“沉重的、严重的”，形容伤害、损失或过错极其严重。',C('grievous.s1','事故调查','The collision caused grievous injuries to two passengers, so investigators closed the road while emergency crews transported them to hospital.','碰撞使两名乘客受了重伤，因此调查人员封闭道路，急救人员将他们送往医院。','The collision caused grievous injuries to two passengers / so investigators closed the road / while emergency crews transported them to hospital.','grievous 常修饰 injuries、harm、loss 等严重伤害；so 表示事故处理结果。','伤势严重到需要急救和送院，符合词义。'),M('The report called a tiny paper cut a grievous injury requiring no care and causing no pain.','The report called the paper cut a minor injury requiring little care and causing little pain.','轻微纸割伤不符合 grievous 所表示的严重程度。'),[Q('grievous',1,1,'Grievous harm is?','extremely serious','barely noticeable','entirely imaginary','grievous 表示非常严重。'),Q('grievous',2,1,'Which loss could be called grievous?','a major loss of life after a disaster','one missing paper clip','a small delay of two seconds','重大人员伤亡可称 grievous loss。'),Q('grievous',3,1,'The closest synonym for grievous in “grievous injury” is?','severe','trivial','cheerful','severe 表示严重的。'),Q('grievous',4,1,'A grievous offense is one that is?','very serious','harmless and minor','a friendly greeting','grievous 可修饰严重罪行或过错。')]);
P('grill','grill 经古法语与拉丁语 craticula“细格栅”发展，可指烧烤食物、严厉盘问、烤架，也可指烧烤店或烧烤餐。',C('grill.s2','正式质询','The committee grilled the contractor about missed safety checks, asking for dates, records, and an explanation for each failure.','委员会就遗漏的安全检查严厉盘问承包商，要求提供日期、记录并解释每一次疏漏。','The committee grilled the contractor / about missed safety checks / asking for dates, records, / and an explanation for each failure.','grill + 人 + about 表示严厉盘问；asking 列出追问内容。','连续追问疏漏和证据，体现 s2。'),M('The committee grilled the contractor by asking one casual question and ending the meeting immediately.','The committee questioned the contractor briefly by asking one casual question and ending the meeting immediately.','随意简短地提问不符合 grill 的长时间严厉盘问义。'),[Q('grill',1,1,'To grill vegetables is to?','cook them over or under direct heat','store them in a freezer','wash them with cold water only','grill 的烹饪义是直接加热烤制。'),Q('grill',2,2,'A reporter grilled the official by?','questioning the official intensely for a long time','cooking the official’s lunch','greeting the official at the door','动词 grill 也指严厉盘问。'),Q('grill',3,3,'A metal grill used outdoors is?','a device with bars for cooking food','a complaint about unfair treatment','a kind of grey bear','grill 可作烤架名词。'),Q('grill',4,4,'A neighborhood grill may be?','a restaurant serving grilled food','a map coordinate square','a geological survey','grill 也可指烧烤店或烧烤餐。')]);
P('grilled','grilled 是 grill 的过去分词形容词，表示食物经烤架或直接热源烤制而成。',C('grilled.s1','菜单介绍','The café served grilled vegetables with lemon dressing, letting the charred edges add flavor without covering the freshness of the produce.','咖啡馆供应配柠檬酱汁的烤蔬菜，让微焦的边缘增添风味，同时保留食材的新鲜感。','The café served grilled vegetables with lemon dressing / letting the charred edges add flavor / without covering the freshness / of the produce.','grilled 修饰 vegetables，说明烹饪方式；without 表示烤制没有掩盖食材本味。','蔬菜放在热源上烤出焦边，符合 grilled。'),M('The grilled peppers were raw and had never been exposed to heat.','The fresh peppers were raw and had never been exposed to heat.','未经加热的生辣椒不能称 grilled。'),[Q('grilled',1,1,'Grilled food has been?','cooked on a grill or direct heat','frozen without cooking','stored in a sealed jar only','grilled 表示经过烤制。'),Q('grilled',2,1,'Which dish is grilled?','fish cooked over hot coals','cold fruit served straight from a bowl','dry rice before it is boiled','炭火上烹熟的鱼是 grilled fish。'),Q('grilled',3,1,'Grilled differs from boiled because grilled food is?','cooked by direct radiant heat','cooked fully submerged in water','never heated at all','烧烤依靠直接热源，煮食浸在水中加热。'),Q('grilled',4,1,'A grilled sandwich may have?','toasted, browned surfaces','uncooked frozen bread','a paper grid instead of food','烤制三明治表面常会烤黄。')]);
P('grim','grim 源自古英语或日耳曼语系词源，可形容严峻不快、表情冷酷、面对困难坚定，也可表示糟糕讨厌。',C('grim.s1','就业报告','The employment outlook remained grim after the factory closed, with few replacement jobs available in the surrounding towns.','工厂关闭后，就业前景仍很严峻，周边城镇几乎没有可替代的工作。','The employment outlook remained grim / after the factory closed / with few replacement jobs / available in the surrounding towns.','grim 修饰 outlook，表示令人担忧；with 短语列出悲观原因。','可用岗位稀少使前景严峻，符合 s1。'),M('The grim outlook promised abundant jobs, rising wages, and no risk of unemployment.','The optimistic outlook promised abundant jobs, rising wages, and no risk of unemployment.','岗位充足、工资上涨的乐观前景与 grim 相反。'),[Q('grim',1,1,'A grim outlook is?','serious and worrying','cheerful and reassuring','unrelated to the future','grim 可表示严峻、令人担忧。'),Q('grim',2,2,'A grim expression may look?','stern and unfriendly','warm and welcoming','colorful and playful','s2 指表情严厉冷峻。'),Q('grim',3,3,'A grim determination is?','firm resolve despite difficulty','an inability to make any effort','a cheerful greeting','grim 还可表示不屈、坚定。'),Q('grim',4,4,'Which situation is grim?','a badly damaged town with little food or shelter','a pleasant picnic on a sunny day','a successful party with enough supplies','极端困难和匮乏可称 grim。')]);
P('grime','grime 源自古英语 grima“污垢、污渍”，指厚重、常呈黑色的脏污。',C('grime.s1','清洁维护','Years of engine oil and road dust had formed a layer of grime on the workshop floor, so the crew used a degreaser before repainting it.','多年的机油和道路灰尘在车间地板上积成一层污垢，因此工人先用除油剂清洁再重新刷漆。','Years of engine oil and road dust / had formed a layer of grime / on the workshop floor / so the crew used a degreaser before repainting it.','a layer of grime 指一层厚污垢；so 引出清洁措施。','油污和灰尘积成厚层，符合 grime。'),M('The floor’s grime was a spotless layer of clean paint with no dirt or oil.','The floor’s coating was a spotless layer of clean paint with no dirt or oil.','洁净无污的涂层不是 grime。'),[Q('grime',1,1,'Grime is?','thick, often dark dirt','a clean coat of paint','a kind greeting','grime 指厚重污垢。'),Q('grime',2,1,'Where might grime build up?','on machinery exposed to oil and dust','inside a freshly washed glass','on a clean sheet of paper kept sealed','机器接触油尘会积累污垢。'),Q('grime',3,1,'Which word is closest to grime?','muck','gleam','greeting','muck 表示污泥、脏东西。'),Q('grime',4,1,'A layer of grime should usually be?','cleaned off','celebrated as a greeting','used to measure a grid','污垢通常需要清除。')]);
P('grimly','grimly 由 grim 加副词后缀 -ly 构成，表示严肃冷峻地、没有幽默感地，或带着阴郁态度。',C('grimly.s1','风险汇报','“The repairs will take months,” the engineer said grimly, pointing to the cracked supports and the rising water below the bridge.','“维修要花几个月。”工程师神情严峻地说着，指向开裂的支撑结构和桥下上涨的水位。','“The repairs will take months,” the engineer said grimly / pointing to the cracked supports / and the rising water below the bridge.','grimly 修饰 said，说明说话方式严肃阴郁；pointing 补充令人担忧的证据。','严重风险使工程师以冷峻、忧虑的方式报告情况。'),M('She grimly laughed with cheerful delight at the harmless joke and showed no concern at all.','She laughed cheerfully at the harmless joke and showed no concern at all.','轻松愉快且毫无忧虑不符合 grimly 的阴郁严肃语气。'),[Q('grimly',1,1,'To speak grimly is to speak?','sternly or with gloom','in a carefree, joking way','without making any sound','grimly 表示严肃阴郁地。'),Q('grimly',2,1,'A grimly delivered warning would sound?','serious and without humor','playful and celebratory','impossible to understand because it is whispered','严肃、无幽默感的警告体现 grimly。'),Q('grimly',3,1,'Which sentence uses grimly naturally?','He grimly accepted that the repairs could not be delayed.','He grimly giggled at a harmless cartoon with delight.','He grimly painted the wall greenish by accident.','严肃接受令人不快的事实符合副词用法。'),Q('grimly',4,1,'The closest opposite of grimly is?','cheerfully','sternly','gloomily','cheerfully 表示愉快地。')]);
P('grimy','grimy 由 grime 加 -y 构成，形容被厚重、常带黑色的污垢弄脏。',C('grimy.s1','街区清洁','The grimy bus windows were covered with road dust and fingerprints, making the view difficult to see on the ride home.','满是道路灰尘和指纹的公交车窗脏兮兮的，回家路上很难看清窗外景色。','The grimy bus windows were covered with road dust and fingerprints / making the view difficult to see / on the ride home.','grimy 修饰 windows，指被厚污垢弄脏；making 说明脏窗造成的结果。','灰尘和指纹覆盖玻璃，符合 grimy。'),M('The grimy window was spotless, transparent, and free from every mark.','The clean window was spotless, transparent, and free from every mark.','毫无污渍的窗户不应称 grimy。'),[Q('grimy',1,1,'A grimy jacket is?','covered with thick dirt','freshly washed and spotless','made of clean white paper','grimy 表示脏污的。'),Q('grimy',2,1,'Which object looks grimy?','a blackened tool coated with old grease','a polished glass with no marks','a new shirt sealed in clean packaging','油污覆盖的工具显得 grimy。'),Q('grimy',3,1,'The closest word to grimy is?','dirty','gleaming','genuine','dirty 表示肮脏。'),Q('grimy',4,1,'A grimy wall should be?','cleaned to remove the dirt','called spotless without looking','used to send holiday greetings','清洁墙面可除去污垢。')]);
P('grin','grin 可作动词或名词，源自古英语 grennian，表示露齿而笑；也可指尴尬或勉强挤出的笑。',C('grin.s2','尴尬反应','When the presenter forgot the next line, he grinned awkwardly, glanced at the cue cards, and continued after a brief pause.','主持人忘了下一句时尴尬地咧嘴一笑，瞥了眼提示卡，停顿片刻后继续。','When the presenter forgot the next line / he grinned awkwardly / glanced at the cue cards / and continued after a brief pause.','grin 可带 awkwardly 描写尴尬或勉强的一笑；when 从句交代原因。','忘词后的尴尬露齿笑符合 s2。'),M('She grinned with embarrassment while showing no teeth and keeping a completely neutral face.','She remained expressionless with embarrassment, showing no teeth and keeping a neutral face.','没有任何笑容或露齿动作不能称为 grin。'),[Q('grin',1,1,'To grin is to?','smile widely with the teeth showing','frown without moving the lips','speak in a low angry voice','grin 指露齿咧嘴笑。'),Q('grin',2,2,'An embarrassed grin may be?','a forced or uneasy smile','a shout of anger','a formal written complaint','grin 可指尴尬或勉强的笑。'),Q('grin',3,3,'A grin is?','a wide smile showing the teeth','a deep sadness caused by loss','a device for grinding grain','grin 的名词义是露齿笑。'),Q('grin',4,1,'Which reaction is a grin?','she smiles broadly after recognizing a friend','she groans because her knee hurts','she grieves at a funeral','宽阔的笑容是 grin。')]);
P('grind','grind 源自古英语 grindan“磨、碾”，可指磨碎、磨快或磨牙，也可名词化指枯燥辛苦的劳作。',C('grind.s4','日常工作','After months of the daily grind, the nurses welcomed a quiet weekend away from schedules, alarms, and paperwork.','经历数月日复一日的枯燥辛劳后，护士们很欢迎一个远离排班、警报和文书工作的安静周末。','After months of the daily grind / the nurses welcomed a quiet weekend / away from schedules, alarms, / and paperwork.','the daily grind 是固定表达，指枯燥辛苦的日常工作。','繁重、重复的工作让人疲惫，符合 s4。'),M('She described the repetitive paperwork as a relaxing holiday rather than a daily grind.','She described the repetitive paperwork as a daily grind rather than a relaxing holiday.','重复文书工作令人疲惫而非假期。'),[Q('grind',1,1,'To grind coffee beans is to?','crush them into smaller pieces','tie them into a bundle','wash them without breaking them','grind 的常见义是磨碎。'),Q('grind',2,2,'To grind a knife is to?','sharpen or smooth its edge by rubbing','make its handle longer with paint','use it to greet a visitor','grind 也可表示磨快刀刃。'),Q('grind',3,3,'If someone grinds their teeth, the teeth?','rub together with a harsh sound','are sharpened on a whetstone','are arranged into a grid','grind 可指上下牙摩擦。'),Q('grind',4,4,'The daily grind refers to?','hard, dull, tiring routine work','a festive holiday','a new invention','daily grind 指枯燥辛苦的日常劳作。')]);
P('grinder','grinder 由 grind 加施事者后缀 -er 构成，指把材料磨碎或碾碎的机器。',C('grinder.s1','厨房设备','The coffee grinder broke one morning, so the café used a hand mill to crush the beans until a replacement arrived.','一天早晨咖啡研磨机坏了，因此咖啡馆改用手摇磨豆机，直到新机器送到。','The coffee grinder broke one morning / so the café used a hand mill / to crush the beans / until a replacement arrived.','grinder 作机器名词；to crush 说明研磨机的用途。','机器把咖啡豆磨碎，符合 grinder。'),M('The grinder was a machine that joined whole beans together without crushing or cutting them.','The grinder was a machine that crushed whole beans into smaller particles.','研磨机的功能是磨碎，不是把豆子粘在一起。'),[Q('grinder',1,1,'A coffee grinder is a machine that?','crushes beans into smaller particles','keeps coffee hot by boiling it','measures a cup’s color','grinder 指研磨机。'),Q('grinder',2,1,'Which tool is a grinder?','a device that turns grain into flour','a greeting card sent to a friend','a net used to locate map squares','把谷物磨成面粉的机器是 grinder。'),Q('grinder',3,1,'A grinder differs from a storage jar because it?','changes material by crushing it','only holds material without processing it','is always made of paper','研磨机会加工、碾碎材料。'),Q('grinder',4,1,'The closest verb related to grinder is?','grind','greet','grieve','grinder 派生自动词 grind。')]);
P('grinding','grinding 是 grind 的 -ing 形容词，可描述长期压迫、沉重而不间断的处境，也可描述物体摩擦时刺耳的声音。',C('grinding.s1','生活压力','The family endured grinding poverty for years, working long hours while still struggling to afford heat and basic food.','这家人多年承受着难以摆脱的贫困，长时间工作仍难以负担取暖和基本食物。','The family endured grinding poverty for years / working long hours / while still struggling to afford heat / and basic food.','grinding 修饰 poverty，指持续沉重、令人精疲力竭的困境。','长期贫困带来持续压力和困苦，符合 s1。'),M('The grinding poverty was brief, comfortable, and ended before anyone had to work.','The temporary hardship was brief, comfortable, and ended before anyone had to work.','舒适、短暂且无需劳作与 grinding poverty 相反。'),[Q('grinding',1,1,'Grinding poverty is?','oppressive and difficult for a long time','a brief and comfortable holiday','a noise made by metal rubbing','grinding 可形容长期沉重的贫困。'),Q('grinding',2,2,'A grinding noise often comes from?','hard objects rubbing against each other','a soft greeting whispered kindly','a plant growing in a garden','摩擦产生的刺耳声是 s2。'),Q('grinding',3,1,'Which phrase uses grinding figuratively?','years of grinding routine','a grinding wheel sharpening steel','a grinding sound from the brakes','长年枯燥沉重的日常是比喻用法。'),Q('grinding',4,2,'A grinding brake sound suggests?','friction between parts','a quiet engine with no contact','a happy greeting from a passenger','刺耳摩擦声暗示部件相磨。')]);
P('grip','grip 源自日耳曼语系中“抓握”的词，可作动词表示紧握或吸引注意，名词可指握力、控制权或理解掌握。',C('grip.s4','知识学习','After several worked examples, Mina finally got a grip on the probability rule and could explain why the two events were not independent.','做过几个例题后，米娜终于掌握了概率规则，并能解释为什么这两个事件并不独立。','After several worked examples / Mina finally got a grip on the probability rule / and could explain / why the two events were not independent.','get a grip on + 知识表示理解、掌握；finally 表示学习后达到理解。','她能够解释规则及其应用，表明已经掌握该知识。'),M('He had a firm grip on the topic but could not explain one idea and understood none of it.','He had no real grip on the topic and could not explain one idea.','完全不理解与掌握主题矛盾。'),[Q('grip',1,1,'To grip a rail is to?','hold it very tightly','decorate it with a garland','grill it over a fire','动词 grip 可表示紧握。'),Q('grip',2,2,'A story grips its readers when it?','holds their attention strongly','makes them forget how to read','measures their hand strength','grip 可比喻牢牢吸引注意。'),Q('grip',3,3,'A good grip on a tool means?','a firm hold or control','a deep sadness','a kind of greeting','grip 名词可指紧握或控制力。'),Q('grip',4,4,'To get a grip on a concept is to?','understand or master it','hold it physically in a fist','complain about it repeatedly','固定短语意为理解、掌握。')]);
P('gripe','gripe 可作动词或名词，表示对恼人的事情发牢骚；名词 gripe 常指反复提起的小抱怨。',C('gripe.s2','日常抱怨','His main gripe about the new app was that it sent too many notifications, even after he had turned most alerts off.','他对新应用最大的牢骚是通知太多，即使他已经关掉大多数提醒也仍然如此。','His main gripe about the new app / was that it sent too many notifications / even after he had turned most alerts off.','gripe 作名词，gripe about + 事物表示抱怨；that 从句说明具体不满。','他反复抱怨通知太多，符合名词义 s2。'),M('Her gripe praised the app for sending exactly the right number of helpful alerts.','Her compliment praised the app for sending exactly the right number of helpful alerts.','称赞功能恰当不是抱怨。'),[Q('gripe',1,1,'To gripe about a delay is to?','complain about it','celebrate it','measure it','gripe 作动词表示抱怨。'),Q('gripe',2,2,'A small repeated gripe is?','a complaint','a guarantee','a greeting','名词 gripe 指牢骚或抱怨。'),Q('gripe',3,1,'Which comment is a gripe?','“The bus app keeps showing the wrong arrival time.”','“Thank you for fixing the app.”','“The bus stop is two blocks away.”','对错误到站时间的抱怨属于 gripe。'),Q('gripe',4,1,'The closest verb to gripe is?','grumble','greet','gather','grumble 表示抱怨。')]);
P('grippe','grippe 经法语 grippe 而来，是 influenza 的旧称，指流感，尤其指严重病例。',C('grippe.s1','医学史记录','The old diary says the entire household was bedridden with grippe that winter, using a historical name for influenza.','旧日记记载那年冬天全家都因 grippe 卧床不起；这是流感的一个历史称呼。','The old diary says the entire household was bedridden with grippe that winter / using a historical name / for influenza.','grippe 是旧式或历史用语，指 influenza；同位说明避免误认为另一种病名。','整户人因流感卧床，符合 grippe。'),M('The physician used grippe to mean a harmless greeting exchanged at dinner.','The physician used greeting to mean a kind word exchanged at dinner.','grippe 是疾病名称，不是问候用语。'),[Q('grippe',1,1,'Grippe is an older name for?','influenza','a metal cooking rack','a complaint about unfair treatment','grippe 指流感。'),Q('grippe',2,1,'An old record saying someone had grippe means the person had?','influenza','a broken bone from a fall','a cold room lit by gas','旧记录中的 grippe 指流感。'),Q('grippe',3,1,'Grippe is most likely found in?','historical or older medical writing','a map key for grid coordinates','a guide to greetings','grippe 是旧式流感名称。'),Q('grippe',4,1,'The closest modern term to grippe is?','flu','grime','grit','flu 是 influenza 的常用简称。')]);
P('grit','grit 源自古英语 greot“沙砾”，名词可指细小硬砂，也可比喻勇气与毅力；动词短语 grit one’s teeth 表示咬紧牙关。',C('grit.s1','道路维护','Workers spread grit across the icy path to improve traction and help pedestrians avoid slipping.','工人把砂砾撒在结冰的小路上以增加摩擦力，帮助行人避免滑倒。','Workers spread grit across the icy path / to improve traction / and help pedestrians / avoid slipping.','grit 作物质名词指粗砂或沙砾；to improve 说明撒砂目的。','细小砂粒增加抓地力，符合 grit 的物质义。'),M('The grit on the path was a smooth liquid that reduced traction and made the ice more slippery.','The oil on the path was a liquid that reduced traction and made the ice more slippery.','增加抓地力的沙砾不是降低摩擦的液体。'),[Q('grit',1,1,'Grit spread on an icy road is?','small hard particles such as sand','a warm bowl of gruel','a type of greeting','grit 可指沙砾。'),Q('grit',2,1,'A person with grit shows?','courage and perseverance','a tendency to avoid every challenge','a dislike of all vegetables','比喻义 grit 指勇气与毅力。'),Q('grit',3,1,'To grit one’s teeth is to?','clench them firmly','smile with the teeth showing','grind coffee beans','固定说法表示咬紧牙关。'),Q('grit',4,1,'Which person shows grit?','someone who keeps studying after repeated setbacks','someone who quits at the first minor difficulty','someone who refuses every responsibility','经历挫折仍坚持体现毅力。')]);
P('grizzly','grizzly 源于 grizzle/grizzled“灰白、斑白”的词族，常指北美西北部的大型灰熊，也可形容毛发或表面灰白斑驳。',C('grizzly.s1','野生动物观察','A grizzly crossed the riverbank at a distance, and the wildlife guide asked the hikers to remain together and give the bear space.','一头灰熊在远处横穿河岸，野生动物向导让徒步者保持队形并给熊留出距离。','A grizzly crossed the riverbank at a distance / and the wildlife guide asked the hikers / to remain together / and give the bear space.','grizzly 作名词指灰熊；后文以 bear 回指该动物。','大型熊类在野外出现，符合 s1。'),M('The grizzly was a small seabird that plunged into the ocean to catch fish.','The gannet was a seabird that plunged into the ocean to catch fish.','grizzly 指熊；俯冲捕鱼的海鸟是 gannet。'),[Q('grizzly',1,1,'A grizzly is a type of?','large North American bear','small antelope','metallic element','grizzly bear 是北美大型熊类。'),Q('grizzly',2,2,'A grizzly coat or surface is?','streaked or flecked with grey','bright red from end to end','made of clean white paper','s2 形容灰白斑驳。'),Q('grizzly',3,1,'Where might a grizzly be observed?','in a North American wilderness area','inside an aircraft galley','in a Greek alphabet list','灰熊生活在北美野外地区。'),Q('grizzly',4,1,'The closest animal to a grizzly is?','a brown bear','a gazelle','a gannet','grizzly 属于熊类。')]);
P('groan','groan 源自古英语 grānian，可作动词表示因疼痛发出低沉呻吟、抱怨或发出嘎吱声，也可作名词指这种声音。',C('groan.s4','现场反应','A low groan rose from the audience when the projector failed again, and the technician hurried to check the cable.','投影仪再次失灵时，观众席传来一阵低沉抱怨声，技术员赶紧检查电缆。','A low groan rose from the audience / when the projector failed again / and the technician hurried / to check the cable.','groan 作名词指低沉呻吟或抱怨声；when 引出声音出现的原因。','观众发出的低沉抱怨声属于名词义 s4。'),M('The audience gave a groan of delight while cheering loudly for the projector failure.','The audience gave a cheer of delight while cheering loudly for the projector failure.','欢呼表达高兴，不是 groan 所指的呻吟或抱怨。'),[Q('groan',1,1,'To groan in pain is to?','make a long, low sound','smile widely with teeth showing','speak in a cheerful greeting','动词 groan 可表示疼痛呻吟。'),Q('groan',2,2,'To groan about a delay is to?','complain in an annoyed way','welcome the delay gladly','measure how long it lasts','groan 也可表示抱怨。'),Q('groan',3,3,'A floorboard may groan when it?','makes a low creaking sound under pressure','turns into a metal grid','is painted greenish','木板受压发出低沉嘎吱声是 s3。'),Q('groan',4,4,'A groan from the crowd is?','a low sound of pain or complaint','a bright greeting card','a precise measurement','groan 可作名词指低沉抱怨声。')]);
P('grocer','grocer 经法语 grocery/grocer 词族发展，指经营食品及日常家庭用品的店主或食品杂货商。',C('grocer.s1','社区商店','The grocer kept fresh bread near the entrance and stocked rice, soap, and canned vegetables on shelves behind the counter.','食品杂货店店主把新鲜面包放在入口附近，并在柜台后面的货架上摆放大米、肥皂和罐装蔬菜。','The grocer kept fresh bread near the entrance / and stocked rice, soap, and canned vegetables / on shelves behind the counter.','grocer 指店主或经营者；stocked 列出商店所售食品和家庭用品。','店主售卖食品及日用品，符合词义。'),M('The grocer repaired broken bones in an operating room and never sold food or household supplies.','The surgeon repaired broken bones in an operating room and never sold food or household supplies.','修复骨骼是外科医生的工作，不是杂货商。'),[Q('grocer',1,1,'A grocer is a shopkeeper who sells?','food and household supplies','only legal services','ships powered by oars','grocer 指食品杂货商。'),Q('grocer',2,1,'Which customer might visit a grocer?','someone buying bread, rice, and soap','someone seeking a family tree','someone measuring magnetic fields','购买食物和日用品可去杂货店。'),Q('grocer',3,1,'The grocer restocked the shelves means the grocer?','put more goods out for sale','removed every product permanently','closed the shop and left','店主补货就是把商品重新摆上货架。'),Q('grocer',4,1,'The closest place to a grocer’s work is?','a grocery shop','a geophysical lab','a football gridiron','食品杂货商通常在杂货店工作。')]);
P('grocery','grocery 源自 grocery/grocer 词族，指售卖日常食品的杂货店；美式英语常用 grocery store。',C('grocery.s1','购物地点','They stopped at the small grocery on the corner to buy milk, apples, and bread before the shop closed for the evening.','他们在街角的小杂货店停下，在商店晚上打烊前买了牛奶、苹果和面包。','They stopped at the small grocery on the corner / to buy milk, apples, and bread / before the shop closed for the evening.','grocery 在该词条中作地点名词，指卖食品的小店；to buy 列出购买目的。','顾客进店购买食品，符合 grocery 的词条义。'),M('The grocery sold no food and served only as a place to repair bicycles.','The bicycle shop sold no food and served only as a place to repair bicycles.','只修自行车、不卖食品的店不是 grocery。'),[Q('grocery',1,1,'A grocery is a shop that sells?','food and everyday provisions','medical operations','tickets for football matches','grocery 指食品杂货店。'),Q('grocery',2,1,'Which item would you commonly buy at a grocery?','milk','a geologist’s rock hammer','a ship’s galley stove','牛奶是杂货店常见商品。'),Q('grocery',3,1,'In American English, a grocery store is also called a?','grocery','garrison','grotto','grocery 可指杂货店。'),Q('grocery',4,1,'A grocery differs from a restaurant because a grocery mainly?','sells food to take home','serves cooked meals at tables','teaches customers to cook professionally','杂货店主要零售食物，餐馆提供餐食。')]);
P('groom','groom 经古法语与日耳曼语词源发展，可作名词指新郎，也可作动词表示清洁、梳理和照料人或动物。',C('groom.s1','动物护理','Before the show, the handler groomed the horse carefully, brushing its coat and checking that its mane lay neatly.','表演前，饲养员仔细给马梳理打扮，刷理毛皮并检查鬃毛是否整齐。','Before the show / the handler groomed the horse carefully / brushing its coat / and checking that its mane lay neatly.','groom + 动物表示清洁梳理；brushing 和 checking 说明具体护理步骤。','刷理马匹毛发和鬃毛体现动词义。'),M('The handler groomed the horse by leaving its coat muddy and tangled before the show.','The handler neglected the horse by leaving its coat muddy and tangled before the show.','泥泞打结说明没有梳理照料，而非 groom。'),[Q('groom',1,1,'To groom a horse is to?','clean and brush its coat','measure its gait with a grid','feed it only greetings','groom 动词表示梳理、照料动物。'),Q('groom',2,1,'A groom at a wedding is the?','bridegroom','person who prints the gazette','person who operates a grinder','groom 也可作名词，指新郎。'),Q('groom',3,1,'Which action is grooming?','combing a dog and checking its coat','leaving the animal dirty','building a fence around the field','梳理动物毛发属于 grooming。'),Q('groom',4,1,'A horse was groomed before the show. This means it was?','cleaned and made neat','made to gallop at full speed','left without care','groom 作动词指清洁整理。')]);
P('groove','groove 可指硬表面上的长槽、唱片纹路或固定生活节奏，也可作动词表示刻出槽纹。',C('groove.s3','工作节奏','Once the team found its groove, members completed the weekly review smoothly without rushing or overlooking details.','团队找到工作节奏后，成员便能顺利完成每周审查，不再匆忙，也不会漏掉细节。','Once the team found its groove / members completed the weekly review smoothly / without rushing / or overlooking details.','find one’s groove 是惯用表达，指找到适合自己的节奏或惯常方式。','团队形成稳定高效的工作套路，符合 s3。'),M('The team found its groove by changing its process randomly every hour and never settling into a routine.','The team lost its rhythm by changing its process randomly every hour and never settling into a routine.','每小时随机改变流程、无法形成稳定节奏与 found its groove 矛盾。'),[Q('groove',1,1,'A groove in wood is?','a long, narrow cut or channel','a friendly greeting','a thick layer of dirt','groove 可指表面的长槽。'),Q('groove',2,2,'A record’s groove is?','the track followed by the needle','a family relationship','a place for grilling food','唱片槽纹引导唱针移动。'),Q('groove',3,3,'To find your groove at work is to?','settle into an effective routine','cut a channel into metal','complain repeatedly','groove 的比喻义是形成稳定节奏。'),Q('groove',4,4,'To groove a piece of wood is to?','cut a narrow channel into it','paint it greenish','serve it as a greeting','动词 groove 表示刻槽。')]);
P('grope','grope 源自中古英语或日耳曼语系中“摸索”的词，可指看不见时用手探摸、艰难前行、费力寻找思路，也可作名词指摸索动作。',C('grope.s3','问题求解','Without enough evidence to answer directly, the researchers groped for an explanation by comparing the few measurements they had.','由于证据不足以直接作答，研究人员通过比较有限的测量结果，费力寻找解释。','Without enough evidence to answer directly / the researchers groped for an explanation / by comparing the few measurements / they had.','grope for + 抽象目标表示艰难探寻答案或想法；by 引出尝试方式。','研究者缺乏明确答案，只能费力探索解释，符合 s3。'),M('The researchers groped for an answer by reading the exact solution printed clearly on the first page.','The researchers found the answer immediately by reading the exact solution printed clearly on the first page.','答案清楚现成、立即读到，不是费力摸索。'),[Q('grope',1,1,'To grope in darkness is to?','feel around with the hands because you cannot see','walk confidently using a bright map','grill food over coals','grope 可指黑暗中用手摸索。'),Q('grope',2,2,'To grope forward in a dark tunnel is to?','move with difficulty because vision is limited','run easily in broad daylight','stand still and greet visitors','s2 指在看不清时艰难前行。'),Q('grope',3,3,'To grope for an explanation is to?','search for an idea with difficulty','state a proven answer immediately','decorate a plate','grope for 抽象目标指费力寻找。'),Q('grope',4,4,'A grope is?','an act of feeling about blindly','a formal guarantee','a warm greeting','名词 grope 指盲目摸索的动作。')]);
P('gross','gross 源自法语与拉丁语 grossus“粗大、整体的”，可指扣除项目前的总额、粗俗恶心、严重明显，也可作动词表示赚得总额。',C('gross.s1','财务核算','The company reported gross revenue of two million dollars before deducting payroll, rent, taxes, and other operating costs.','公司报告称总收入为两百万美元，尚未扣除工资、租金、税费和其他运营成本。','The company reported gross revenue of two million dollars / before deducting payroll, rent, taxes, / and other operating costs.','gross revenue 指扣除成本前的总收入；before deducting 明确其计算口径。','金额尚未减去费用，符合 s1。'),M('The company called its net profit gross revenue even though it had already deducted all costs and taxes.','The company called its pre-deduction total gross revenue before subtracting costs and taxes.','已扣完成本税费的是净额，不是 gross 总额。'),[Q('gross',1,1,'Gross income is measured?','before taxes or other deductions are removed','after every expense has been subtracted','only by counting the company’s employees','gross 表示扣除前的总额。'),Q('gross',2,2,'A gross joke is?','rude or disgusting','polite and refined','a precise scientific measurement','gross 的第二义是粗俗、令人恶心。'),Q('gross',3,3,'A gross error is?','very serious or clearly wrong','a harmless greeting','a tiny color difference','gross 可形容严重或明显的错误。'),Q('gross',4,5,'If a business grosses five million dollars, it?','earns that total before deductions','loses exactly five million dollars','spends that amount on one item','动词 gross 表示总共赚得（扣除前）。')]);
P('grossly','grossly 由 gross 加 -ly 构成，常作程度副词表示极其、严重地，也可表示粗略或粗俗地。',C('grossly.s1','规则遵循','The contractor was grossly negligent because he ignored repeated warnings about unstable scaffolding while workers were still on the platform.','承包商严重疏忽，因为工人仍在脚手架上时，他无视了关于脚手架不稳的多次警告。','The contractor was grossly negligent / because he ignored repeated warnings / about unstable scaffolding / while workers were still on the platform.','grossly 修饰 negligent，表示程度极其严重；because 给出疏忽事实。','多次无视严重安全警告，体现 grossly negligent。'),M('The contractor was grossly careful and followed every safety rule without exception.','The contractor was consistently careful and followed every safety rule without exception.','严格遵守全部安全规则不应称 grossly negligent。'),[Q('grossly',1,1,'Grossly negligent means?','extremely careless in a serious way','slightly attentive','politely appreciative','grossly 常作程度副词，意为极其、严重地。'),Q('grossly',2,2,'To estimate something grossly is to estimate it?','roughly, without fine precision','with exact laboratory accuracy','in a rude tone of voice','grossly 也可表示粗略地。'),Q('grossly',3,1,'Which phrase is natural?','grossly unfair treatment','gross unfairly treatmently','grossly fairness treatment','grossly 可修饰 unfair，表示极其不公平。'),Q('grossly',4,1,'A grossly exaggerated claim is?','exaggerated to an extreme degree','measured with exact precision','understated slightly','grossly 表示程度非常大。')]);
P('grotto','grotto 经意大利语 grotta 以及拉丁语 crypta 词源发展，指小而有景致的天然洞穴，也可指园林中人工仿造的洞室。',C('grotto.s1','园林景观','A narrow path led visitors to an artificial grotto beside the pond, where shells and stones decorated the shaded interior.','一条窄径把访客引到池塘旁的人造洞室，阴凉的内部装饰着贝壳和石头。','A narrow path led visitors to an artificial grotto beside the pond / where shells and stones decorated / the shaded interior.','artificial grotto 指人工洞室；where 从句描述洞内装饰。','园林中仿造的小洞穴符合词义。'),M('The grotto was a skyscraper office tower with glass walls and fifty floors.','The grotto was a small cave-like chamber with a shaded interior.','高层办公楼不是小型洞穴或洞室。'),[Q('grotto',1,1,'A grotto is?','a small picturesque cave or cave-like chamber','a large factory chimney','a map grid for locating streets','grotto 指景致小洞穴或人工洞室。'),Q('grotto',2,1,'Where might an artificial grotto be built?','in a landscaped garden near a pond','at the top of a radio tower','inside a grocery checkout lane','园林水池旁可能建人工洞室。'),Q('grotto',3,1,'A natural grotto is closest to a?','small cave','large open field','metal cooking rack','grotto 与小洞穴接近。'),Q('grotto',4,1,'Which feature might decorate a grotto?','shells and stones in a shaded chamber','rows of office desks in a skyscraper','a railway signal on an open track','贝壳和石头可装饰洞室。')]);
P('grouchy','grouchy 由 grouch（爱发牢骚的人）加 -y 构成，可形容容易恼火、脾气不好或常常抱怨的人。',C('grouchy.s2','旅途抱怨','After the long delay, the grouchy passenger complained about the seat, the snack, and even the announcements over the speaker.','长时间延误后，这位爱抱怨的乘客对座位、点心甚至广播通知都发起牢骚。','After the long delay / the grouchy passenger complained about the seat, the snack, / and even the announcements / over the speaker.','grouchy 修饰 passenger；并列项显示其抱怨范围很广。','乘客不断抱怨各种小事，体现 s2。'),M('The grouchy guest praised everything warmly and did not complain once.','The cheerful guest praised everything warmly and did not complain once.','热情赞扬且不抱怨与 grouchy 相反。'),[Q('grouchy',1,1,'A grouchy person is often?','bad-tempered and easily annoyed','calmly pleased with every situation','unable to recognize colors','grouchy 指脾气坏、易烦。'),Q('grouchy',2,2,'A grouchy reply may sound?','complaining and angry','warmly welcoming','precisely measured','s2 强调抱怨和发牢骚。'),Q('grouchy',3,1,'Which behavior is grouchy?','snapping at others over small inconveniences','thanking a helper politely','laughing kindly at a joke','因小事对人发火是 grouchy。'),Q('grouchy',4,1,'The closest opposite of grouchy is?','cheerful','irritable','complaining','cheerful 表示愉快，与坏脾气相反。')]);
P('ground','ground 是多义词，可指地面、用途场地、理由或知识基础，也可作动词指停飞/搁浅，或形容食物被磨碎。',C('ground.s3','法律论证','The judge found no ground for dismissing the case because the filing had been submitted on time and met the required procedure.','法官认为没有理由驳回此案，因为文件按时提交并符合规定程序。','The judge found no ground for dismissing the case / because the filing had been submitted on time / and met the required procedure.','ground 作单数名词可指理由或依据；no ground for + 动名词是常见搭配。','程序符合要求，因此没有驳回案件的根据，符合 s3。'),M('The court dismissed the case on no ground, meaning it had several strong legal reasons to do so.','The court dismissed the case on solid legal grounds, meaning it had strong reasons to do so.','no ground 表示没有依据，与“有充分理由”相反。'),[Q('ground',1,1,'The ground beneath a building is?','the solid surface of the Earth','a written guarantee','a kind greeting','ground 的基本义是地面。'),Q('ground',2,2,'A football ground is?','an area of land used for sport','a group of electrical cables','a reason for a legal claim','ground 可指运动场地。'),Q('ground',3,3,'“There is no ground for the complaint” means?','there is no valid reason or basis','the complaint was made outdoors','the complaint has been ground into powder','ground 可指理由、依据。'),Q('ground',4,5,'The airline grounded the aircraft means it?','stopped it from flying','made it land permanently in a field','ground it into small pieces','ground 作动词可指停飞。')]);
P('ground beef','ground beef 由 ground（磨碎的）与 beef（牛肉）构成，指切碎或绞碎的牛肉；英式英语常称 minced beef。',C('ground beef.s1','食品准备','The recipe calls for lean ground beef, which the cook browns in a pan before adding tomatoes and beans.','食谱要求使用瘦碎牛肉，厨师先在锅里将它炒至变色，再加入番茄和豆子。','The recipe calls for lean ground beef / which the cook browns in a pan / before adding tomatoes and beans.','ground 修饰 beef，表示肉已绞碎；brown the meat 指炒至表面变色。','锅中炒制的牛肉碎符合 ground beef。'),M('The recipe calls for ground beef, so the cook adds an intact whole steak without cutting it.','The recipe calls for a whole steak, so the cook adds it intact without grinding it.','未切碎的整块牛排不是 ground beef。'),[Q('ground beef',1,1,'Ground beef is?','beef that has been minced or ground into small pieces','a whole uncut steak','a type of ground used in football','ground beef 指绞碎牛肉。'),Q('ground beef',2,1,'In British English, ground beef is commonly called?','minced beef','grey beef','grilled beef','minced beef 是英式常用说法。'),Q('ground beef',3,1,'Which dish might use ground beef?','a meat sauce made with minced beef','a fruit salad with no meat','a bowl of gruel made only from oats','肉酱常使用牛肉碎。'),Q('ground beef',4,1,'Why is the beef called ground?','it has been mechanically minced or crushed','it was found lying on the floor','it has been cooked on a gridiron','ground 指经过研磨、绞碎处理。')]);
P('groundbreaking','groundbreaking 由 ground 与 break 构成，惯用形容新颖且具有重要影响、开创先例的发现或工作。',C('groundbreaking.s1','科研成果','The team published a groundbreaking study showing that a low-cost sensor could detect contamination much earlier than existing equipment.','团队发表了一项开创性研究，表明低成本传感器能比现有设备更早检测到污染。','The team published a groundbreaking study / showing that a low-cost sensor / could detect contamination / much earlier than existing equipment.','groundbreaking 修饰 study，表示具有新颖性和重要影响；showing 引出研究贡献。','新方法显著早于现有设备检测污染，具有开创意义。'),M('The groundbreaking report repeated an unchanged result from decades ago and introduced no new finding.','The routine report repeated an unchanged result from decades ago and introduced no new finding.','没有新内容或重要影响的报告并非 groundbreaking。'),[Q('groundbreaking',1,1,'A groundbreaking discovery is?','new and important enough to change a field','a routine result with no new effect','a complaint about unfair treatment','groundbreaking 指开创性且重要的。'),Q('groundbreaking',2,1,'Which project sounds groundbreaking?','the first reliable test that detects a disease years earlier','a copy of a standard form with no changes','a routine schedule posted each week','首次可靠地提前检测疾病具有创新性。'),Q('groundbreaking',3,1,'A groundbreaking law may?','establish a major new approach','repeat an existing rule without change','describe the ground under a building','开创性法律会确立新的重要做法。'),Q('groundbreaking',4,1,'The closest contrast to groundbreaking is?','conventional','innovative','pioneering','conventional 表示传统、常规。')]);
P('grounding','grounding 由 ground 加 -ing 构成，此处指对某学科事实或技能的扎实入门基础；在其他语境也可指接地，但本词条收录的是基础义。',C('grounding.s1','技能训练','The apprenticeship gave Noor a grounding in basic electrical safety before she began assisting licensed technicians on site.','学徒培训先为努尔打下电气安全基础，然后她才开始在现场协助持证技术人员。','The apprenticeship gave Noor a grounding in basic electrical safety / before she began assisting / licensed technicians on site.','give someone a grounding in + 学科/技能，指提供扎实基础。','训练先教安全基本知识，符合 grounding 的基础义。'),M('The short course gave Noor no grounding in safety and taught only advanced tasks without any basics.','The short course gave Noor no preparation in safety and taught only advanced tasks without any basics.','完全不教基本知识就没有为该领域打基础。'),[Q('grounding',1,1,'A grounding in biology is?','a solid introduction to the subject’s basic facts','a complaint about unfair treatment','a device that cooks food','grounding 指基础知识或入门训练。'),Q('grounding',2,1,'A good course gives beginners grounding by?','teaching core concepts before advanced work','skipping every basic skill','requiring expertise before instruction','先教核心概念可帮助打基础。'),Q('grounding',3,1,'Which phrase is natural?','a grounding in mathematics','a grounding at mathematics to','a groundedly mathematics','grounding 常与 in 连用。'),Q('grounding',4,1,'A solid grounding helps a learner?','build further skills on reliable basics','avoid learning the subject','replace every fact with a guess','扎实基础支持后续学习。')]);
P('groundless','groundless 由 ground 加否定后缀 -less 构成，表示缺少事实、理由或依据的。',C('groundless.s1','谣言核查','The allegation was groundless: bank records showed that the missing funds had never entered the treasurer’s account.','这项指控毫无根据：银行记录显示，失踪资金从未进入财务主管的账户。','The allegation was groundless / bank records showed / that the missing funds had never entered / the treasurer’s account.','groundless 修饰 allegation，表示没有事实依据；冒号后提供反证。','银行记录否定指控内容，说明其没有根据。'),M('The claim was groundless because multiple signed documents and video footage directly supported it.','The claim was well supported because multiple signed documents and video footage directly supported it.','多份文件和影像提供直接证据，不能称为 groundless。'),[Q('groundless',1,1,'A groundless rumor is?','unsupported by facts or evidence','confirmed by many reliable records','a map grid for locating roads','groundless 表示没有事实根据。'),Q('groundless',2,1,'Which accusation is groundless?','one disproved by records and unsupported by evidence','one confirmed by several independent witnesses','one backed by signed documents','缺少证据且被记录推翻的指控是 groundless。'),Q('groundless',3,1,'The closest opposite of groundless is?','well founded','unsupported','baseless','well founded 表示有充分依据。'),Q('groundless',4,1,'Why call a fear groundless?','there is no reasonable evidence for the danger','a real threat has been confirmed','the danger is visible and immediate','没有合理证据支持危险时可称 groundless。')]);
P('groundnut','groundnut 由 ground 与 nut 构成，指果实在地下成熟的花生；在部分地区该词也可指某些其他地下结实植物。',C('groundnut.s1','作物生长','After flowering, the groundnut plant sends its fruiting stems into the soil, where the pods develop underground.','花生开花后，结果枝会钻入土中，豆荚在地下发育。','After flowering / the groundnut plant sends its fruiting stems into the soil / where the pods develop underground.','groundnut 指地下结荚的花生；where 从句说明果荚形成位置。','豆荚在土中成熟，解释 groundnut 的命名与词义。'),M('The groundnut grows its pods high above the soil on a tree branch.','The groundnut develops its pods underground after the fruiting stems enter the soil.','花生荚果在地下形成，不是在树枝上高处生长。'),[Q('groundnut',1,1,'A groundnut is commonly known as a?','peanut','gannet','grey bear','groundnut 指花生。'),Q('groundnut',2,1,'Why is the plant called a groundnut?','its pods develop underground','it grows only on rocky cliffs','it produces metal from the soil','花生果荚在地下生长。'),Q('groundnut',3,1,'Which food may contain groundnuts?','peanut butter','a bowl of plain water','a steel fence','花生酱由花生制成。'),Q('groundnut',4,1,'A groundnut plant forms its pods?','below the soil surface','inside a bird’s nest','on a high tree branch','果荚在地下发育。')]);
P('grounds','grounds 是 ground 的复数形式，可指房屋、机构周围的土地，也可指提出主张或采取行动的理由、依据。',C('grounds.s1','场所管理','The museum grounds include a sculpture garden, a wooded path, and several benches open to visitors during daylight hours.','博物馆园区包括雕塑花园、一条林间小路和几张长椅，白天向访客开放。','The museum grounds include a sculpture garden / a wooded path / and several benches / open to visitors during daylight hours.','grounds 作复数名词指建筑周围的土地或园区；include 后列举设施。','花园、小路和长椅构成博物馆周边园区。'),M('The museum grounds were the legal reasons for dismissing a complaint, not any land around the building.','The grounds for dismissing the complaint were legal reasons, not the museum’s surrounding land.','句中讨论建筑周围土地时，grounds 不应被解释为理由。'),[Q('grounds',1,1,'The grounds of a museum are?','the land and outdoor areas around it','the museum’s legal complaints','a set of cooking grills','grounds 可指建筑周围园区。'),Q('grounds',2,1,'“Grounds for appeal” means?','reasons that justify an appeal','land surrounding a house','a patch of vegetables','grounds 也指理由或依据。'),Q('grounds',3,1,'Which sentence uses grounds to mean land?','The school grounds have a sports field and garden.','The court found no grounds for the claim.','She grounds the coffee before breakfast.','学校操场和花园是周边场地。'),Q('grounds',4,1,'Which phrase uses grounds to mean reasons?','grounds for refusing the request','the grounds behind the manor','school grounds near the river','grounds for refusing 表示拒绝的理由。')]);
P('groundwater','groundwater 由 ground 与 water 合成，指存在于地表以下土壤孔隙和多孔岩层中的地下水。',C('groundwater.s1','水资源监测','The town tested groundwater from several wells after heavy rains, checking for bacteria and chemicals that might have seeped below the fields.','暴雨后，镇上检测了几口井的地下水，检查是否有细菌和化学物质从田地渗入地下。','The town tested groundwater from several wells / after heavy rains / checking for bacteria and chemicals / that might have seeped below the fields.','groundwater 作不可数名词指地下含水层中的水；that 从句修饰可能渗入的污染物。','井水来自地下土壤和岩层，符合 groundwater。'),M('The groundwater flowed in clouds high above the fields rather than below the soil.','The rainfall formed clouds above the fields, while groundwater remained below the soil.','地表下的水不是高空云层。'),[Q('groundwater',1,1,'Groundwater is water found?','below the surface in soil or porous rock','only inside clouds','on top of a sealed roof','groundwater 指地下水。'),Q('groundwater',2,1,'A well can draw?','groundwater from below the land','greetings from a postcard','grit from a metal grinder','井可抽取地下水。'),Q('groundwater',3,1,'Why monitor groundwater near farms?','chemicals may seep down into it','it is always visible above the soil','it cannot be affected by land use','农田化学物质可能渗入地下水。'),Q('groundwater',4,1,'The closest contrast to groundwater is?','surface water in a river','water stored underground','water in porous rock','河流地表水与地下水相对。')]);
P('group','group 可作名词指聚集在一起的人或物、公司集团或乐队，也可作动词表示分类归组或聚集。',C('group.s2','音乐表演','The jazz group recorded its first album in a small studio, with each musician contributing a different arrangement.','这支爵士乐队在一家小录音室录制了首张专辑，每位乐手都贡献了不同的编曲。','The jazz group recorded its first album in a small studio / with each musician contributing / a different arrangement.','group 作名词指乐队；with 结构说明成员的参与方式。','多名乐手组成爵士乐队，符合 s2。'),M('The jazz group was one person playing alone and had no other musicians.','The solo musician played alone and had no other members in a group.','单人独奏者不是由多名成员组成的乐队。'),[Q('group',1,1,'A group of hikers is?','several people gathered together','one person traveling alone','a single map square','group 指聚在一起的人或物。'),Q('group',2,2,'A music group is?','a band of performers','a water source underground','a court complaint','group 可指音乐团体或乐队。'),Q('group',3,3,'To group items by color is to?','put them into categories','remove all items from the room','measure their weight only','动词 group 表示归类。'),Q('group',4,4,'When birds group together, they?','form a cluster or gather','become a single bird','stop moving forever','group 可作动词表示聚集。')]);
P('grouse','grouse 可作名词指生活在荒原、可供狩猎的松鸡，也可作动词表示发牢骚或抱怨。',C('grouse.s2','旅途抱怨','The passengers groused about the delay, but the driver explained that a fallen tree had blocked the road ahead.','乘客们对延误发牢骚，但司机解释说前方道路被倒下的树挡住了。','The passengers groused about the delay / but the driver explained / that a fallen tree had blocked / the road ahead.','grouse about + 令人不满的事表示抱怨；but 引出解释。','乘客因延误表达不满，符合动词义 s2。'),M('The passengers groused about the delay by praising it as the best part of their trip.','The passengers praised the delay as the best part of their trip.','称赞延误不是发牢骚。'),[Q('grouse',1,1,'A grouse is a?','plump game bird living on moors','large metal generator','small garden cave','grouse 可指松鸡。'),Q('grouse',2,2,'To grouse about a late bus is to?','complain about it','welcome it happily','measure its speed','动词 grouse 表示抱怨。'),Q('grouse',3,1,'Which habitat may contain grouse?','open moorland','an aircraft galley','a deep ocean trench','松鸡常生活在荒原。'),Q('grouse',4,2,'A grouse over a noisy neighbor is?','a complaint','a seabird','a greeting','名词义也可指牢骚。')]);
P('grove','grove 源自古英语 graf“树丛、林地”，指面积不大的树木群，常用于描述果园或小树林。',C('grove.s1','自然景观','A small oak grove shaded the footpath near the stream, providing a quiet resting place for hikers at midday.','溪边的一小片橡树林为小径遮阴，在正午为徒步者提供了安静的休息处。','A small oak grove shaded the footpath near the stream / providing a quiet resting place / for hikers at midday.','grove 指一小片树木；a grove of + 树种也是常见搭配。','一小片橡树为行人遮荫，符合 grove。'),M('The grove was a treeless patch of bare pavement with no plants or shade.','The courtyard was a treeless patch of bare pavement with no plants or shade.','没有树木的空地不是 grove。'),[Q('grove',1,1,'A grove is?','a small group or stand of trees','a noisy complaint','a place to buy meat','grove 指小树林。'),Q('grove',2,1,'An orange grove contains?','many orange trees growing together','one isolated office tower','a row of gas lamps','橙树林由成片橙树组成。'),Q('grove',3,1,'Where might someone find a grove?','in a small wooded area beside a path','inside an aircraft cockpit','on a map legend only','树林常出现在小径旁的绿地。'),Q('grove',4,1,'The closest word to grove is?','copse','grievance','grill','copse 指小树林。')]);
P('grovel','grovel 可能与古诺尔斯语 grufla“俯伏、匍匐”有关，可指面朝下爬行，也可比喻卑躬屈膝以讨好或求饶。',C('grovel.s2','职场互动','He refused to grovel for approval, instead presenting the evidence calmly and asking the committee to judge the proposal on its merits.','他拒绝卑躬屈膝地讨好以求认可，而是平静地陈述证据，请委员会根据提案本身的优点作判断。','He refused to grovel for approval / instead presenting the evidence calmly / and asking the committee / to judge the proposal on its merits.','grovel for + favor/approval 表示卑屈地求取；instead 对照坚定、得体的行为。','拒绝卑躬屈膝求认可，说明 grovel 指讨好式屈从。'),M('The manager grovelled confidently and independently, refusing to flatter anyone or seek favor.','The manager stood firm and confidently, refusing to flatter anyone or seek favor.','不屈从、不讨好与 grovel 相反。'),[Q('grovel',1,2,'To grovel for favor is to?','act in a servile way to gain approval','walk proudly without seeking anyone’s help','measure a room’s floor','grovel 可比喻卑躬屈膝求取好处。'),Q('grovel',2,1,'A frightened animal may grovel by?','lying or moving with its body close to the ground','flying above a tree','standing tall and roaring','动词字面义指俯伏或匍匐。'),Q('grovel',3,2,'Which action is groveling in the figurative sense?','apologizing repeatedly and flattering a boss to avoid blame','presenting evidence calmly and accepting a fair decision','asking a neutral question','反复讨好上司以求免责体现卑屈。'),Q('grovel',4,1,'The closest contrast to grovel is?','stand up for oneself','crawl submissively','act servilely','坚定维护自己与卑屈相反。')]);
P('grow','grow 源自古英语 growan，可指生长发育、种植作物、数量增加或逐渐变成某种状态。',C('grow.s3','经济变化','The cooperative expects sales to grow steadily as more neighborhood shops begin ordering its locally made preserves.','随着更多社区商店开始订购本地制作的果酱，合作社预计销售额会稳步增长。','The cooperative expects sales to grow steadily / as more neighborhood shops begin ordering / its locally made preserves.','grow 作不及物动词表示数量增加；as 从句说明增长原因。','销售额随订单增加而扩大，符合 s3。'),M('The cooperative’s sales grew by shrinking from 500 orders to just 20.','The cooperative’s sales fell by shrinking from 500 orders to just 20.','订单数减少是下降，不是增长。'),[Q('grow',1,1,'A child grows when the child?','becomes bigger or develops over time','is ground into powder','stops changing permanently','grow 常指生长或发育。'),Q('grow',2,2,'To grow tomatoes is to?','plant and care for the crop','buy only cooked tomatoes','draw a grid over a tomato','grow 可表示种植、栽培。'),Q('grow',3,3,'If a business grows, it?','increases in size or amount','becomes smaller every year','turns into a greeting','grow 也表示扩大或增加。'),Q('grow',4,4,'“She grew more confident” means she gradually?','became more confident','planted confidence in a garden','measured confidence with a ruler','grow + 形容词表示逐渐变得。')]);
P('grower','grower 由 grow 加施事者后缀 -er 构成，可指种植某种作物的农户或公司，也可指具有特定生长习性的植物。',C('grower.s1','农业供应链','The berry grower installed drip irrigation to keep young plants watered during dry weeks without wasting water between the rows.','浆果种植者安装滴灌系统，让幼苗在干旱周保持供水，同时避免浪费行间用水。','The berry grower installed drip irrigation / to keep young plants watered during dry weeks / without wasting water / between the rows.','grower 指种植作物的人或企业；to keep 引出安装灌溉的目的。','种植并照料浆果作物的人属于 grower。'),M('The berry grower never planted or cared for berries and only sold used furniture.','The furniture dealer never planted or cared for berries and only sold used furniture.','不种植、不照料作物的人不是 berry grower。'),[Q('grower',1,1,'A berry grower is?','a farmer or business that raises berry crops','a person who only eats berries','a machine that cuts metal','grower 可指作物种植者。'),Q('grower',2,2,'A fast grower is a plant that?','increases in size quickly','sells fruit at a market','grows only after being ground','s2 指生长习性较快的植物。'),Q('grower',3,1,'Which worker is a grower?','someone who cultivates grapes for sale','someone who repairs a ship’s galley','someone who studies only family history','栽培葡萄出售是种植者工作。'),Q('grower',4,1,'The closest role to a grower is?','cultivator','grievance officer','guardian','cultivator 指栽培者。')]);
P('growl','growl 源自模仿低沉动物声响的词，指动物或人发出的低沉、愤怒的咆哮声。',C('growl.s1','动物行为','The dog gave a low growl when a stranger reached toward its food bowl, so the owner calmly called it away.','陌生人伸手靠近食盆时，狗低声咆哮，主人便平静地把它叫开。','The dog gave a low growl / when a stranger reached toward its food bowl / so the owner calmly called it away.','give a growl 表示发出低吼；so 引出主人谨慎处理的后果。','低沉、带警告意味的狗叫是 growl。'),M('The dog gave a friendly growl by purring softly and wagging its tail at every stranger.','The dog gave a friendly greeting by purring softly and wagging its tail at every stranger.','轻柔呼噜和摇尾欢迎不是带愤怒意味的 growl。'),[Q('growl',1,1,'A dog growls when it?','makes a low, often angry sound','smiles broadly with its teeth showing','sings a high birdlike tune','growl 指低沉咆哮声。'),Q('growl',2,1,'A person might growl a reply when?','speaking in a low, angry voice','whispering a cheerful greeting','reading silently','人也可用低沉愤怒的声音说话。'),Q('growl',3,1,'Which sound is a growl?','a low rumbling warning from an animal','a bright bell ringing clearly','a soft page turning','低沉动物警告声是 growl。'),Q('growl',4,1,'The closest synonym for growl is?','snarl','greet','grieve','snarl 表示龇牙咆哮。')]);
P('grown','grown 是 grow 的过去分词，也常作形容词表示已长大、发育成熟的。',C('grown.s1','家庭关系','Their grown children now live in different cities, but they return home each year to help their parents with the harvest.','他们已经长大的孩子如今住在不同城市，但每年仍回家帮父母收割。','Their grown children now live in different cities / but they return home each year / to help their parents / with the harvest.','grown 修饰 children，表示孩子已成年或长大；but 对照独立生活与回家帮忙。','孩子已长大并独立居住，符合 grown。'),M('The grown child was a newborn who could not sit up or speak.','The newborn child could not sit up or speak.','新生儿尚未长大，不宜称 grown child。'),[Q('grown',1,1,'A grown child is?','fully developed or adult','newly born and unable to sit','a plant that has been ground','grown 可表示长大的、成年了的。'),Q('grown',2,1,'The phrase “grown children” usually means?','adult children','children who are still toddlers','children who work as guardians','grown children 指成年子女。'),Q('grown',3,1,'Which sentence uses grown as an adjective?','Their grown son moved to another city.','The plant grows each spring.','They ground the beans finely.','grown 修饰 son，表示已长大。'),Q('grown',4,1,'A grown tree is?','fully developed','a seed that has just been planted','a tree cut into powder','grown 可形容成熟的植物。')]);
P('grown-up','grown-up 由 grown 与 up 组成，作名词指成年人；作形容词时也可表示成熟、成年人的。',C('grown-up.s1','家庭对话','The child asked a grown-up to help reach the top shelf, then carefully explained which book she needed.','孩子请一位成年人帮忙拿到最上层的书架，随后仔细说明她需要哪本书。','The child asked a grown-up to help reach the top shelf / then carefully explained / which book she needed.','a grown-up 作可数名词指成年人；to help 表示请求其协助。','孩子向成年人求助，体现名词义。'),M('The toddler was the only grown-up in the room and every adult was a baby.','The toddler was the youngest child in the room and every other person was an adult.','幼儿不是成年人，不能称 grown-up。'),[Q('grown-up',1,1,'A grown-up is?','an adult person','a very young baby','a map coordinate','grown-up 作名词指成年人。'),Q('grown-up',2,1,'Which person is a grown-up?','a parent attending a school meeting','a newborn in a crib','a small seed underground','家长属于成年人。'),Q('grown-up',3,1,'In “grown-up responsibilities,” grown-up is?','an adjective meaning adult or mature','a noun for a greeting','a verb meaning to grind','此处 grown-up 作形容词修饰 responsibilities。'),Q('grown-up',4,1,'A child asking a grown-up for help is asking?','an adult','a grizzly bear','a grocery store','grown-up 指成人。')]);
P('growth','growth 由 grow 加 -th 构成，指体积、数量或程度变大的过程，也可指生物生长。',C('growth.s1','城市发展','The town’s rapid growth increased demand for housing and transit, so planners reviewed how new neighborhoods could connect to existing services.','城镇快速发展增加了住房和公共交通需求，因此规划人员审查新社区如何接入现有服务。','The town’s rapid growth increased demand for housing and transit / so planners reviewed / how new neighborhoods could connect / to existing services.','growth 指规模或数量增加；so 引出发展带来的规划需求。','人口和城镇规模增加导致需求上升，符合增长义。'),M('The town’s growth meant its population and services became smaller every year.','The town’s decline meant its population and services became smaller every year.','规模逐年缩小是 decline，不是 growth。'),[Q('growth',1,1,'Economic growth means?','an increase in economic activity or output','a decrease in every measure','a type of metal cooking rack','growth 表示增加或发展。'),Q('growth',2,1,'A plant’s growth includes?','becoming larger as it develops','being converted into a greeting','staying exactly the same forever','植物长大是 growth。'),Q('growth',3,1,'Rapid population growth may create?','greater demand for housing and services','fewer residents in every case','a smaller need for transit','人口增长可能提高公共服务需求。'),Q('growth',4,1,'The closest opposite of growth is?','decline','increase','development','decline 表示下降或衰退。')]);
P('grudge','grudge 可作名词指长期怨恨，也可作动词表示记仇，或不情愿地给予、因嫉妒而舍不得。',C('grudge.s3','长期关系','Years after the dispute, neither neighbor held a grudge, and they cooperated again on repairs to the shared fence.','争执多年后，两位邻居都不再怀恨在心，并重新合作修理共用围栏。','Years after the dispute / neither neighbor held a grudge / and they cooperated again / on repairs to the shared fence.','hold a grudge 是固定搭配，指长期怀恨；neither 表示双方均已放下。','不再保留长期怨恨符合名词义 s3。'),M('She held a grudge by forgetting the argument immediately and feeling no anger toward him.','She let go of her grudge by forgetting the argument and feeling no anger toward him.','立即原谅、毫无怨气说明放下 grudge，而非怀恨。'),[Q('grudge',1,1,'To hold a grudge is to?','keep angry feelings about a past wrong','offer a warm greeting','measure a piece of land','grudge 可指长期记仇。'),Q('grudge',2,2,'To grudge someone a privilege is to?','feel unwilling to let them have it','give it gladly and generously','teach them how to use it','动词 grudge 也可表示不情愿给予。'),Q('grudge',3,3,'A grudge is?','a lasting feeling of resentment','a type of groundwater','a fruit grown underground','名词 grudge 指积怨。'),Q('grudge',4,1,'Which phrase is common?','hold a grudge against someone','hold a grudge at someone to','hold a grudge with someone on','常见搭配 hold a grudge against。')]);
P('grudging','grudging 由 grudge 加 -ing 构成形容词，表示不情愿地给予、承认或接受，常暗示勉强。',C('grudging.s1','工作评价','The reviewer gave the project grudging praise, admitting that its results were useful while still criticizing the team’s poor documentation.','评论者勉强称赞了该项目，承认结果有用的同时仍批评团队记录不佳。','The reviewer gave the project grudging praise / admitting that its results were useful / while still criticizing / the team’s poor documentation.','grudging 修饰 praise，表示虽承认优点但并非欣然赞许。','评论者不情愿地承认成果有用，体现 grudging。'),M('Her grudging approval was delighted and freely offered without any hesitation.','Her enthusiastic approval was delighted and freely offered without any hesitation.','欣然且毫不犹豫地赞同与勉强相反。'),[Q('grudging',1,1,'A grudging apology is?','given unwillingly or with resentment','offered warmly and without hesitation','never spoken or written','grudging 表示不情愿的。'),Q('grudging',2,1,'Which response is grudging?','“Fine, I will help,” he said after being pressed repeatedly.','“I would be delighted to help,” she said at once.','“No one asked me,” he said calmly.','被反复催促后勉强答应体现 grudging。'),Q('grudging',3,1,'Grudging praise means the speaker?','admits something is good but does so reluctantly','celebrates it with unreserved enthusiasm','has not heard about it','勉强赞扬带有保留和不情愿。'),Q('grudging',4,1,'The closest opposite of grudging is?','willing','reluctant','resentful','willing 表示自愿。')]);


P('gruel','gruel 经古法语发展而来，指用谷物煮成的稀粥或稀薄谷物汤，常见于传统或简朴饮食描写。',C('gruel.s1','传统饮食','The diary describes a simple breakfast of gruel made from oats and water, served warm when the family had little else to eat.','日记写道，早餐是一碗燕麦和水煮成的稀粥；家里没什么别的食物时，便趁热端来吃。','The diary describes a simple breakfast of gruel / made from oats and water / served warm / when the family had little else to eat.','gruel 指稀薄谷物粥；made from 说明原料。','燕麦加水煮成的稀粥符合词义。'),M('The gruel was a thick roast steak served dry without any grain or liquid.','The meal was a thick roast steak served dry without any grain or liquid.','干烤牛排不是稀薄谷物粥。'),[Q('gruel',1,1,'Gruel is?','a thin cooked cereal or grain soup','a grilled steak','a clear greeting card','gruel 指谷物稀粥。'),Q('gruel',2,1,'Which meal is gruel?','oats simmered in plenty of water until thin','a whole turkey roasted until crisp','uncooked grains sealed in a jar','谷物加水煮成稀薄食物是 gruel。'),Q('gruel',3,1,'Gruel has traditionally been associated with?','simple, basic food','a formal wedding dessert','a metal cooking rack','gruel 常被描写为简朴食物。'),Q('gruel',4,1,'The closest food to gruel is?','thin porridge','dry pastry','raw salad','thin porridge 与稀粥相近。')]);
P('gruff','gruff 的历史词源不完全确定；现代用法可形容声音低沉粗哑，也可形容说话突然、生硬而显得不礼貌。',C('gruff.s1','语音描述','The guard answered in a gruff voice after the night shift, his words low and rough but still clear enough to understand.','守卫值完夜班后用粗哑的声音回答，语调低而粗糙，但仍足够清楚。','The guard answered in a gruff voice after the night shift / his words low and rough / but still clear enough to understand.','gruff 修饰 voice，指声音低沉粗哑；but 表示声音虽粗仍能听懂。','低沉而粗糙的嗓音符合 s1。'),M('The gruff singer spoke in a delicate, high, sweet voice that sounded perfectly smooth.','The gentle singer spoke in a delicate, high, sweet voice that sounded perfectly smooth.','柔和清亮的声音与 gruff 的粗哑声质相反。'),[Q('gruff',1,1,'A gruff voice sounds?','deep and harsh','high and silky','silent','gruff 可描述低沉粗哑的声音。'),Q('gruff',2,2,'A gruff reply may seem?','abrupt and rather rude','warmly welcoming','carefully measured in a lab','gruff 也可形容生硬态度。'),Q('gruff',3,1,'Which speaker sounds gruff?','a tired guard answering in a rough low tone','a child singing in a clear high voice','a host greeting guests warmly','低沉粗糙的语气体现 gruff。'),Q('gruff',4,1,'The closest contrast to a gruff manner is?','courteous and gentle','abrupt','harsh','courteous and gentle 与生硬粗鲁相反。')]);
P('grumble','grumble 可能源自模仿低沉、含混的声音，表示低声抱怨或发牢骚。',C('grumble.s1','日常通勤','Several riders grumbled about the crowded train, but they moved aside when an older passenger needed a seat.','几位乘客低声抱怨列车拥挤，但一位年长乘客需要座位时，他们还是让了开来。','Several riders grumbled about the crowded train / but they moved aside / when an older passenger needed a seat.','grumble about + 令人不满的事表示抱怨；but 对照抱怨与体贴行动。','乘客对拥挤发牢骚，符合动词义。'),M('He grumbled about the service by praising every delay and thanking staff for being late.','He complimented the service by praising the staff and thanking them.','赞扬并感谢不是抱怨。'),[Q('grumble',1,1,'To grumble is to?','complain, often in a low voice','give a cheerful greeting','make a precise measurement','grumble 表示抱怨。'),Q('grumble',2,1,'Which sound is a grumble?','a quiet mutter about the cold room','a loud celebratory cheer','a clear bird call','低声抱怨的咕哝声是 grumble。'),Q('grumble',3,1,'A person may grumble about?','an annoying delay','a pleasant surprise they welcome','a clear fact they have verified','对令人恼火的延误发牢骚。'),Q('grumble',4,1,'The closest verb to grumble is?','murmur a complaint','greet warmly','gallop quickly','grumble 与低声抱怨相近。')]);
P('grump','grump 作名词指易怒、难取悦的人，也可作动词表示闷闷不乐地抱怨。',C('grump.s2','晨间情绪','He grumped about the early meeting while packing his notes, though he arrived on time and presented his findings clearly.','他一边收拾笔记一边抱怨会议开得太早，不过还是准时到了，并清楚地展示研究结果。','He grumped about the early meeting while packing his notes / though he arrived on time / and presented his findings clearly.','grump 作动词表示闷声抱怨；about 引出抱怨的对象。','他对早会发牢骚，体现动词义 s2。'),M('The grump praised every plan and never complained about anything.','The optimist praised every plan and never complained about anything.','从不抱怨、总是赞扬的人不符合 grump。'),[Q('grump',1,1,'A grump is?','an irritable person who is hard to please','a cheerful greeting','a type of garden tree','grump 名词指脾气坏的人。'),Q('grump',2,2,'To grump about a meeting is to?','complain about it sulkily','organize it with enthusiasm','measure its length exactly','grump 作动词表示闷闷不乐地抱怨。'),Q('grump',3,1,'Which person is a grump?','someone who snaps over small inconveniences','someone who welcomes every guest warmly','someone who studies groundwater','易因小事发火的人是 grump。'),Q('grump',4,1,'The closest adjective to a grump’s mood is?','irritable','genial','grateful','irritable 表示易怒。')]);
P('grumpy','grumpy 由 grump 加 -y 构成，形容容易恼火、脾气不好的状态，也可说明疲劳或生病造成的坏心情。',C('grumpy.s2','身体不适','The grumpy child had a fever and little sleep, so her parents kept the evening quiet and let her rest.','这个孩子发烧又没睡好，心情很差；父母便让晚上安静下来，好让她休息。','The grumpy child had a fever and little sleep / so her parents kept the evening quiet / and let her rest.','grumpy 修饰 child，s2 可指疲倦或生病导致的坏心情；so 引出照护方式。','生病和睡眠不足使孩子情绪差，符合 s2。'),M('The grumpy patient felt cheerful and energetic after a full night of restful sleep.','The refreshed patient felt cheerful and energetic after a full night of restful sleep.','精力充沛、情绪愉快与 grumpy 相反。'),[Q('grumpy',1,1,'A grumpy person is?','bad-tempered and easily annoyed','always calm and pleased','unable to walk','grumpy 表示脾气暴躁。'),Q('grumpy',2,2,'Someone may be grumpy because they are?','tired or ill','well rested and comfortable','measuring a grid','s2 指疲倦或患病造成的情绪差。'),Q('grumpy',3,1,'Which morning mood is grumpy?','snapping at family after barely sleeping','greeting everyone with a warm smile','quietly reading without irritation','缺觉后容易发火体现 grumpy。'),Q('grumpy',4,1,'The closest opposite of grumpy is?','cheerful','irritable','sulky','cheerful 表示开心愉快。')]);
P('guarantee','guarantee 经法语保证术语进入英语，可作动词表示承诺、确保或提供保修，也可作名词指书面保证或保障期限。',C('guarantee.s4','商品保修','The appliance came with a written guarantee covering repairs for two years, provided the owner followed the maintenance instructions.','这台电器附有书面保修单，若主人遵守维护说明，保修期为两年。','The appliance came with a written guarantee / covering repairs for two years / provided the owner followed / the maintenance instructions.','written guarantee 作名词指书面保证文件；covering repairs 说明承诺内容。','随商品附带、列明保修内容的文件是 s4。'),M('The written guarantee promised repairs but explicitly excluded every repair and replacement.','The written notice explained that repairs were excluded and no guarantee was provided.','承诺维修却又排除所有维修，内容自相矛盾。'),[Q('guarantee',1,1,'To guarantee an outcome is to?','promise or make it certain','complain about its fairness','measure it approximately','guarantee 可作动词表示保证。'),Q('guarantee',2,2,'A manufacturer guarantees a product when it?','agrees to repair or replace it if it fails','refuses every service request','sells it without any terms','动词 guarantee 也可指提供保修。'),Q('guarantee',3,3,'A safety measure may guarantee that?','a result is made certain','a rumor is groundless','a guest arrives late','guarantee 可表示确保结果发生。'),Q('guarantee',4,4,'A written guarantee is?','a document promising protection or repairs','a low complaint','a type of grille','guarantee 可作书面保证文件名词。')]);
P('guarantor','guarantor 由 guarantee 加施事者后缀 -or 构成，指作出正式担保的人，常承诺在他人无法履约时承担债务或责任。',C('guarantor.s1','租房手续','The landlord accepted her aunt as a guarantor, requiring a signed promise that the rent would be covered if the tenant could not pay.','房东接受她的姑妈作保证人，要求她签署承诺：如果租客无力支付，租金将由她承担。','The landlord accepted her aunt as a guarantor / requiring a signed promise / that the rent would be covered / if the tenant could not pay.','guarantor 指作出正式担保的人；if 从句说明担保何时生效。','亲属承诺在租客无法支付时承担租金，符合保证人义。'),M('The guarantor refused to make any promise and had no responsibility for the tenant’s debt.','The bystander refused to make any promise and had no responsibility for the tenant’s debt.','不作承诺、无担保责任的人不是 guarantor。'),[Q('guarantor',1,1,'A guarantor is someone who?','formally promises to cover another person’s debt or duty','receives a greeting from a guest','repairs a cooking grill','guarantor 指正式担保人。'),Q('guarantor',2,1,'A rental guarantor may have to pay if?','the tenant cannot meet the rent obligation','the tenant pays on time every month','the landlord paints the wall','担保人在租客未履约时承担责任。'),Q('guarantor',3,1,'Which document might a guarantor sign?','a formal promise to cover specified payments','a menu for grilled food','a map of the property’s grounds only','签署正式付款担保是常见做法。'),Q('guarantor',4,1,'The closest role to a guarantor is a?','surety','guest','grocer','surety 表示保证人。')]);
P('guard','guard 源自古法语 garde，最终与日耳曼语系“看护、防卫”词源有关，可作动词表示保护或提防，名词指警卫或防护装置。',C('guard.s4','运动防护','The player wore a mouth guard during practice to protect his teeth from accidental contact.','球员训练时佩戴护齿套，以防意外碰撞伤到牙齿。','The player wore a mouth guard during practice / to protect his teeth / from accidental contact.','guard 作名词指防护装置；mouth guard 是护齿套。','装置用于保护牙齿免受撞击，符合 s4。'),M('The mouth guard was worn to expose the teeth to injury rather than protect them.','The mouth guard was worn to protect the teeth from injury.','护齿套用途是保护牙齿，不是让牙齿暴露受伤。'),[Q('guard',1,1,'To guard a building is to?','protect or watch over it','decorate it with flowers','grind it into powder','guard 作动词表示守卫、保护。'),Q('guard',2,2,'To guard against infection is to?','take steps to prevent it','invite it to enter','measure it on a map','guard against 表示防范。'),Q('guard',3,3,'A guard at a gate is?','a person protecting the entrance','a type of grievance','a kitchen appliance','guard 可作名词指警卫。'),Q('guard',4,4,'A mouth guard is?','a device that protects the teeth','a person who greets visitors','a tool for measuring rainfall','guard 也可指防护装置。')]);
P('guardian','guardian 源自古法语 garder“看护、保护”，可作名词指照料未成年人的监护人或保护者，也可作形容词表示起保护作用的。',C('guardian.s1','法律照护','After both parents became ill, the court appointed the child’s aunt as guardian to make decisions about schooling and daily care.','父母都生病后，法院指定孩子的姑妈为监护人，负责教育和日常照护决定。','After both parents became ill / the court appointed the child’s aunt as guardian / to make decisions / about schooling and daily care.','appoint someone as guardian 表示指定监护人；to make decisions 说明职责。','姑妈承担孩子法定照护责任，符合 s1。'),M('The guardian was a child who received care from adults but had no responsibility for anyone else.','The ward was a child who received care from a guardian.','接受监护的孩子是 ward，不是 guardian。'),[Q('guardian',1,1,'A child’s guardian is someone who?','looks after the child when the parents cannot','is the child’s guest at a party','sells food at a grocery','guardian 可指未成年人的监护人。'),Q('guardian',2,2,'A guardian wall or device is one that?','serves to protect','causes deliberate damage','measures the Earth’s age','guardian 可作形容词表示起保护作用。'),Q('guardian',3,1,'A court may appoint a guardian to?','make care decisions for a child','sell the child’s school','act as a grizzly bear','监护人负责孩子的照护决定。'),Q('guardian',4,1,'The closest synonym for guardian is?','protector','complainant','grocer','protector 表示保护者。')]);
P('guardianship','guardianship 由 guardian 加 -ship 构成，指依法照料儿童或代其作决定的监护关系或监护权。',C('guardianship.s1','家庭法律','The court reviewed the guardianship arrangement each year to ensure that the child’s needs and living situation were still being addressed.','法院每年审查监护安排，确保孩子的需求和生活状况仍得到妥善照顾。','The court reviewed the guardianship arrangement each year / to ensure / that the child’s needs and living situation / were still being addressed.','guardianship 指监护关系或权利；to ensure 说明定期审查的目的。','法院审查对儿童的法律照护安排，符合 guardianship。'),M('The guardianship ended while the adult continued to make every legal and daily care decision for the child.','The guardianship continued while the adult made legal and daily care decisions for the child.','持续代儿童作照护决定说明监护仍在进行，不是已经结束。'),[Q('guardianship',1,1,'Guardianship is?','legal care and responsibility for a child','a friendly greeting from a guest','a method for grilling food','guardianship 指儿童监护权或监护关系。'),Q('guardianship',2,1,'A guardianship order may specify who?','can make certain decisions for a child','owns the child’s school building','guards a sports field during a match','法院命令可指定监护决策人。'),Q('guardianship',3,1,'The closest related role to guardianship is?','legal custody or care','a greeting card','a geological layer','guardianship 与法定照护相关。'),Q('guardianship',4,1,'Guardianship differs from a casual visit because guardianship?','involves ongoing legal responsibility','lasts only while saying hello','is a type of groundnut','监护具有持续法律责任。')]);
P('guerrilla','guerrilla 经西班牙语 guerrilla“战争、小规模战斗”而来，指以小队形式对抗较大正规军的游击队员或游击式的。',C('guerrilla.s1','历史叙述','The guerrilla fighters operated in small groups against a much larger army, relying on local support and avoiding open battles.','游击队员以小队形式对抗规模大得多的军队，依靠当地支持并避免正面交战。','The guerrilla fighters operated in small groups / against a much larger army / relying on local support / and avoiding open battles.','guerrilla 修饰 fighters，指小规模、非正规作战人员；此例仅作历史描述。','小队对抗大军并避免正面战斗，符合词条描述。'),M('The guerrilla unit was a large conventional army that fought only in formal open battles.','The regular army was a large conventional force that fought in formal open battles.','大规模正规军正面作战与游击队特征不同。'),[Q('guerrilla',1,1,'Guerrilla fighters typically operate?','in small groups against a larger force','as a national weather office','inside a grocery store only','guerrilla 指以小队作战者。'),Q('guerrilla',2,1,'A guerrilla campaign differs from conventional warfare by?','using small units and avoiding direct large-scale battles','using only formal parades','consisting of a single legal complaint','小队行动并避免大规模正面战斗是特点。'),Q('guerrilla',3,1,'The term guerrilla comes from Spanish for?','a small war or conflict','a friendly greeting','a type of cave','词源与西班牙语“小规模战争”有关。'),Q('guerrilla',4,1,'Which phrase is natural?','guerrilla fighters','guerrilla greetings','guerrilla groundnut','该词常修饰 fighters/warfare。')]);
P('guess','guess 经中古英语 gessen 发展而来，表示在信息不充分时推测，也可表示认为或相信某事。',C('guess.s1','日常推断','Without checking the timetable, I guessed that the last train left at ten, so I called the station before setting out.','我没有查时刻表，猜最后一班火车十点发车，因此出发前给车站打了电话。','Without checking the timetable / I guessed that the last train left at ten / so I called the station / before setting out.','guess that 引出缺少把握的判断；后文核实说明这只是推测。','说话人尚未查证，只作可能性判断，符合 s1。'),M('I guessed the train time with complete certainty after reading the official timetable.','I checked the train time with complete certainty after reading the official timetable.','查阅官方时刻表后得到确定信息不是凭有限信息猜测。'),[Q('guess',1,1,'To guess an answer is to?','give an estimate without being sure','report a fact already verified','repeat a question word for word','guess 常指不确定时作推测。'),Q('guess',2,2,'“I guess she is at home” can mean?','I think she is at home, though I am not certain','I have proved she is away','I am asking her to leave','guess 可表示认为、估计。'),Q('guess',3,3,'If you guess correctly by chance, you?','choose the right answer without knowing it beforehand','copy the answer from a key','refuse to answer','guess 也可指碰巧猜对。'),Q('guess',4,4,'A guess is best described as?','an uncertain opinion or estimate','a verified measurement','a formal guarantee','名词 guess 指推测或估计。')]);
P('guest','guest 与古诺尔斯语 gestr“客人”有关，指受邀到家中或活动现场的人，也可指酒店住客或客座参与者。',C('guest.s1','家庭来访','Each guest was asked to leave wet boots by the door before joining the family for dinner.','每位客人都被请在进屋与家人共进晚餐前把湿靴子放在门边。','Each guest was asked to leave wet boots by the door / before joining the family / for dinner.','guest 指受邀来访者；each 后接单数名词和单数谓语。','来访者受主人邀请到家中吃饭，符合 s1。'),M('The guest arrived to stay with friends but was described as the person hosting them.','The host arrived to welcome friends who had been invited to stay.','接待他人的主人是 host，来访者才是 guest。'),[Q('guest',1,1,'A guest at someone’s home is?','a visitor invited or welcomed there','the person who owns every nearby house','a delivery vehicle','guest 指到访的客人。'),Q('guest',2,2,'A hotel guest is someone who?','is staying at the hotel','is employed only to build the hotel','owns the whole city','guest 也指酒店住客。'),Q('guest',3,3,'A guest speaker is?','a visiting speaker invited to an event','the event’s permanent sound system','a person who cancels the event','guest 可作定语表示受邀而来的。'),Q('guest',4,1,'The opposite role to a guest welcoming visitors is the?','host','tourist','neighbor','host 是接待客人的主人。')]);
P('guesthouse','guesthouse 由 guest 和 house 组合而成，指供旅客或来访者住宿的小型旅馆或招待所。',C('guesthouse.s1','旅行住宿','We booked a family-run guesthouse near the old harbor because it offered a quiet room and breakfast before our early ferry.','我们订了老港附近一家家庭经营的旅馆，因为那里有安静的房间，还会在清晨渡船出发前供应早餐。','We booked a family-run guesthouse near the old harbor / because it offered a quiet room and breakfast / before our early ferry.','book a guesthouse 表示预订住宿；because 从句说明选择原因。','旅客预订房间并过夜，符合小型旅馆义。'),M('They booked a guesthouse for the night, but the building had no rooms and was used only as a warehouse.','They booked a warehouse for storage because it had no rooms for travelers.','没有住宿房间的仓库不是供旅客住宿的 guesthouse。'),[Q('guesthouse',1,1,'A guesthouse is usually?','a small place providing lodging for travelers','a workshop for repairing railway tracks','a court that hears legal appeals','guesthouse 指小型住宿场所。'),Q('guesthouse',2,1,'A traveler who books a guesthouse expects to?','sleep there during a visit','buy the entire harbor','attend a court hearing','旅客预订 guesthouse 是为住宿。'),Q('guesthouse',3,1,'Which description best fits a guesthouse?','a modest inn with rooms for visitors','an unoccupied factory with no beds','a public road crossing','小型旅馆为访客提供房间。'),Q('guesthouse',4,1,'A guesthouse is closest in function to a small?','inn','greenhouse','garage','inn 也指小旅馆。')]);
P('guests','guests 是 guest 的复数形式，指两位或更多受邀来访、参加活动或入住的人。',C('guests.s1','活动接待','The guests arrived before the ceremony and signed the register while an usher showed them to their seats.','客人们在仪式开始前到达并在登记册上签名，随后引座员带他们入座。','The guests arrived before the ceremony / and signed the register / while an usher showed them to their seats.','guests 是复数主语，arrived 和 signed 与之搭配；usher 指引座员。','多人到场参加仪式并被接待，符合 guests。'),M('The guests arrived together, but the sentence called them a single visitor throughout.','The guests arrived together, so the sentence refers to several visitors.','guests 是复数形式，不能当作一个 visitor。'),[Q('guests',1,1,'Guests at a wedding are?','people invited to attend it','the couple’s legal documents','the chairs reserved for staff','guests 指受邀参加活动的人。'),Q('guests',2,1,'Several guests means?','more than one visitor','exactly one host','no one has arrived','复数 guests 表示不止一位客人。'),Q('guests',3,1,'A hotel asks its guests to?','follow the house rules during their stay','manage the hotel’s ownership records','serve as the building’s foundations','酒店 guests 是住客。'),Q('guests',4,1,'The singular form of guests is?','guest','guested','guesting','guests 是 guest 的复数形式。')]);
P('guidance','guidance 由 guide 加名词后缀 -ance 构成，指帮助他人作决定、完成任务或找到方向的建议与引导。',C('guidance.s1','学业咨询','Students can seek guidance from the counselor when choosing courses that fit their interests and graduation requirements.','学生在选择符合兴趣和毕业要求的课程时，可以向辅导员寻求指导。','Students can seek guidance from the counselor / when choosing courses / that fit their interests and graduation requirements.','seek guidance from 表示向某人寻求建议；when 引出适用情境。','辅导员提供选课建议和帮助，符合 s1。'),M('The counselor offered guidance by refusing to give any advice or help with course choices.','The counselor offered no guidance and left students to choose courses alone.','拒绝提供任何建议或帮助与 guidance 的含义相反。'),[Q('guidance',1,1,'Guidance from a counselor is?','advice and help with a decision','a receipt for course fees','a list of unrelated guests','guidance 指建议和引导。'),Q('guidance',2,2,'A person seeking guidance wants?','help deciding what to do','a guarantee that no choice is needed','a list of old greetings','寻求 guidance 是希望得到帮助。'),Q('guidance',3,2,'A navigation system provides guidance by?','helping a driver find the route','cooking dinner for passengers','issuing a court judgment','guidance 也可指方向指引。'),Q('guidance',4,1,'The closest synonym for guidance is?','advice','grievance','grime','advice 表示建议，接近 guidance。')]);
P('guide','guide 源于古法语 guider“带路、引导”，可作名词指向导或指南，也可作动词表示带领、指路或指导。',C('guide.s4','野外导航','A ranger guided the hikers along the marked trail and warned them where the path crossed a fast stream.','护林员带领徒步者沿标记好的小径前行，并提醒他们小路经过急流的地点。','A ranger guided the hikers along the marked trail / and warned them / where the path crossed a fast stream.','guide someone along a route 表示带领某人走某条路线；where 从句标出风险位置。','护林员带路并提供路线提醒，符合动词引导义 s4。'),M('The ranger guided the hikers by abandoning them at the trailhead without showing any route.','The ranger guided the hikers by leading them along the marked route.','把徒步者丢在起点而不带路并不是 guide。'),[Q('guide',1,1,'A museum guide may be?','a person who shows visitors around','a visitor’s hotel bill','a metal cooking surface','guide 可作名词指讲解员或向导。'),Q('guide',2,2,'A field guide is usually?','a book that helps identify plants or animals','a person who refuses to give directions','a greeting spoken at a door','guide 可指提供信息的手册。'),Q('guide',3,3,'To guide a traveler is to?','show or lead the traveler along a route','prevent the traveler from moving','sell the traveler’s luggage','动词 guide 表示引路或带领。'),Q('guide',4,4,'A guiding principle is?','a rule or idea that helps direct decisions','a vehicle used on a railway','a visitor staying overnight','guide 也可表示指导决策的原则。')]);
P('guidebook','guidebook 由 guide 与 book 组成，指为旅行者提供地点、路线、服务或观光信息的指南书。',C('guidebook.s1','旅行准备','Her guidebook listed walking routes, museum hours, and inexpensive cafés, which helped her plan a full weekend in the city.','她的旅行指南列出了步行路线、博物馆开放时间和便宜咖啡馆，帮助她安排了完整的城市周末行程。','Her guidebook listed walking routes / museum hours / and inexpensive cafés / which helped her plan a full weekend in the city.','guidebook 指旅行参考书；which 从句说明书中信息的用途。','书中列出旅游地点和实用信息，符合 s1。'),M('The guidebook contained no travel information and consisted only of blank pages.','The notebook contained no travel information and consisted only of blank pages.','只有空白页的笔记本不具备旅行指南的内容。'),[Q('guidebook',1,1,'A travel guidebook commonly includes?','information about places and routes','instructions for growing mold','a formal debt guarantee','guidebook 提供旅行参考信息。'),Q('guidebook',2,1,'Someone might consult a guidebook to find?','museum opening times in a city','the exact thoughts of a stranger','a list of every court sentence','旅行指南常收录开放时间等信息。'),Q('guidebook',3,1,'A guidebook is a kind of?','reference book for visitors or travelers','vehicle for carrying luggage','legal guardian','guidebook 是供游客查阅的书。'),Q('guidebook',4,1,'Which title most likely belongs on a guidebook?','Walking Tours of the Old City','How to Repair a Broken Boiler','The Complete Court Transcript','城市步行路线适合旅行指南。')]);
P('guideline','guideline 由 guide 和 line 组成，指帮助人们作决定或按统一标准办事的建议、原则或规定。',C('guideline.s1','工作规范','The laboratory guideline requires staff to label each sample before it is moved into cold storage.','实验室指南要求工作人员在把样本移入冷藏区前先贴好标签。','The laboratory guideline requires staff to label each sample / before it is moved / into cold storage.','guideline 可指供遵循的正式建议或规则；require 后用不带 to 的不定式。','实验室规定样本转移前必须标记，符合指导规则义 s1。'),M('The laboratory guideline prohibited labels, yet staff claimed it required every sample to be labeled.','The laboratory guideline required each sample to be labeled before storage.','“禁止标签”和“要求贴标签”矛盾，应以真实规范要求为准。'),[Q('guideline',1,1,'A workplace guideline is?','advice or a rule for consistent decisions','a list of visitors at a party','a machine that stores cold air','guideline 指建议、原则或规范。'),Q('guideline',2,2,'A guideline may help employees decide?','how to handle a recurring situation','which guest owns the building','how to change a word into its plural','指导原则帮助处理常见情形。'),Q('guideline',3,2,'Compared with a strict law, a guideline is often?','a recommended standard or direction','a type of soil','a court-appointed person','guideline 常是建议性标准。'),Q('guideline',4,1,'The closest synonym for guideline is?','recommendation','grievance','grill','recommendation 是建议。')]);
P('guild','guild 源自古英语 gild，指从事同一行业或共同目的的组织、协会，也可指网络游戏中的玩家团体。',C('guild.s1','行业组织','The medieval weavers’ guild set standards for apprentices and negotiated rules governing the quality of cloth sold in town.','中世纪织工行会为学徒制定标准，并协商规范城镇布料销售质量的规则。','The medieval weavers’ guild set standards for apprentices / and negotiated rules / governing the quality of cloth sold in town.','guild 指同一行业成员组成的组织；weavers’ 表示织工的所有格。','织工组织制定行业规范，符合 s1。'),M('The weavers’ guild was an unrelated collection of customers with no members working in the trade.','The weavers’ guild was an association of people working in the weaving trade.','完全没有相关行业成员的顾客群体不是织工行会。'),[Q('guild',1,1,'A craft guild historically brought together?','people working in the same trade','people waiting for a train','unrelated trees in a field','guild 指同业者组成的组织。'),Q('guild',2,2,'A guild might set standards for?','training and work within an occupation','the weather on another planet','a guest’s dinner order','行业组织可制定培训和职业规范。'),Q('guild',3,2,'In an online game, a guild is often?','an organized group of players','a type of legal receipt','a solitary player with no contacts','guild 也指游戏中的玩家团体。'),Q('guild',4,1,'The closest synonym for a trade guild is?','association','grudge','greeting','association 表示协会。')]);

})();
